-- ===== allowances-local.sql =====
-- LOCAL PRO ONLY. Montos previstos para materiales por elegir (family 75 of the
-- parity register). Provisional budget lines per job (pro_work) that are later
-- defined with the actual choice and reconciled against the planned amount.
-- Amounts are CRC céntimos (bigint), like work-budget and work-changes.
-- Nothing here creates debt, invoices, charges or notifications: an optional
-- extra for a positive difference is proposed through the existing
-- pro_work_changes_mutate flow (customer approval required) and only linked here.
begin;
create table if not exists public.pro_work_allowances(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,
 position bigint generated always as identity,
 name text not null check(length(btrim(name)) between 1 and 160),
 category text check(category is null or length(btrim(category)) between 1 and 80),
 planned_cents bigint not null check(planned_cents between 0 and 10000000000),
 due_date date,notes text check(notes is null or length(btrim(notes)) between 1 and 1000),
 status text not null default 'open' check(status in('open','decided','reopened')),
 choice_description text check(choice_description is null or length(btrim(choice_description)) between 1 and 300),
 choice_supplier text check(choice_supplier is null or length(btrim(choice_supplier)) between 1 and 160),
 choice_quantity numeric(12,2) check(choice_quantity is null or choice_quantity between 0.01 and 1000000),
 actual_cents bigint check(actual_cents is null or actual_cents between 0 and 10000000000),
 decided_at timestamptz,change_id uuid,archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 check((status='decided')=(choice_description is not null and choice_quantity is not null and actual_cents is not null and decided_at is not null)),
 check(change_id is null or status='decided')
);
create unique index if not exists pro_work_allowance_global_id on public.pro_work_allowances(id);
create index if not exists pro_work_allowance_page on public.pro_work_allowances(owner_id,work_id,position);
create table if not exists public.pro_work_allowance_history(
 owner_id uuid not null,work_id text not null,allowance_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','decide','reopen','archive','restore','link_change')),
 before_item jsonb,after_item jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),foreign key(owner_id,allowance_id) references public.pro_work_allowances(owner_id,id) on delete cascade
);
create index if not exists pro_work_allowance_history_page on public.pro_work_allowance_history(owner_id,work_id,at desc);
create table if not exists public.pro_work_allowance_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
-- Costa Rica calendar day (UTC-6, no DST) used for overdue decisions.
create or replace function public.pro_work_allowance_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (now() at time zone 'America/Costa_Rica')::date $$;
create or replace function public.pro_work_allowance_json(p_row public.pro_work_allowances) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'position',p_row.position,'name',p_row.name,'category',p_row.category,
  'plannedCents',p_row.planned_cents,'dueDate',p_row.due_date,'notes',p_row.notes,'status',p_row.status,
  'choice',case when p_row.status='decided' then jsonb_build_object('description',p_row.choice_description,'supplier',p_row.choice_supplier,
   'quantity',p_row.choice_quantity,'actualCents',p_row.actual_cents,'decidedAt',p_row.decided_at) end,
  'differenceCents',case when p_row.status='decided' then p_row.actual_cents-p_row.planned_cents end,
  'variance',case when p_row.status<>'decided' then null when p_row.actual_cents>p_row.planned_cents then 'over' when p_row.actual_cents<p_row.planned_cents then 'under' else 'equal' end,
  'overdue',p_row.status<>'decided' and not p_row.archived and p_row.due_date is not null and p_row.due_date<public.pro_work_allowance_today(),
  'changeId',p_row.change_id,'archived',p_row.archived,'revision',p_row.revision,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at);
$$;
create or replace function public.pro_work_allowance_totals(p_owner uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('count',count(*),'plannedCents',coalesce(sum(planned_cents),0),
  'decidedPlannedCents',coalesce(sum(planned_cents) filter(where status='decided'),0),'actualCents',coalesce(sum(actual_cents) filter(where status='decided'),0),
  'differenceCents',coalesce(sum(actual_cents-planned_cents) filter(where status='decided'),0),
  'projectedCents',coalesce(sum(case when status='decided' then actual_cents else planned_cents end),0),
  'decidedCount',count(*) filter(where status='decided'),'pendingCount',count(*) filter(where status<>'decided'),
  'overdueCount',count(*) filter(where status<>'decided' and due_date is not null and due_date<public.pro_work_allowance_today()))
 from public.pro_work_allowances where owner_id=p_owner and work_id=p_work and not archived;
$$;
create or replace function public.pro_work_allowances_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;hist jsonb;linked jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid allowance query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select coalesce(jsonb_agg(public.pro_work_allowance_json(a) order by a.archived,a.position),'[]'::jsonb) into items
  from public.pro_work_allowances a where a.owner_id=p_actor and a.work_id=p_work;
 -- QA: live status of each linked extra (it can be accepted, declined or withdrawn
 -- later in Extras y cambios); kept out of the item JSON so stored history is unchanged.
 select coalesce(jsonb_object_agg(c.id::text,c.status),'{}'::jsonb) into linked from public.pro_work_changes c
  where c.owner_id=p_actor and c.work_id=p_work and c.id in(select a.change_id from public.pro_work_allowances a where a.owner_id=p_actor and a.work_id=p_work and a.change_id is not null);
 select coalesce(jsonb_agg(x.content order by x.at desc,x.action_id),'[]'::jsonb) into hist from (
  select h.at,h.action_id,jsonb_build_object('actionId',h.action_id,'allowanceId',h.allowance_id,'action',h.action,'at',h.at,'before',h.before_item,'after',h.after_item) as content
  from public.pro_work_allowance_history h where h.owner_id=p_actor and h.work_id=p_work order by h.at desc,h.action_id limit 100
 ) x;
 return jsonb_build_object('workId',p_work,'today',public.pro_work_allowance_today(),'items',items,'totals',public.pro_work_allowance_totals(p_actor,p_work),'history',hist,'changeStatuses',linked);
end $$;
-- Customer read: only the linked customer of a confirmed/completed request, and
-- only when the owner turned the section on (off by default). No internal notes,
-- revisions, linked change ids or history.
create or replace function public.pro_work_allowances_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;req_status text;enabled boolean;items jsonb;totals jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select coalesce(show_allowances,false) into enabled from public.pro_client_dashboards where owner_id=owner and work_id=wid;
 if req_status not in('confirmed','completed') or not coalesce(enabled,false) then return jsonb_build_object('visible',false);end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'category',a.category,'plannedCents',a.planned_cents,'dueDate',a.due_date,'status',a.status,
   'choice',case when a.status='decided' then jsonb_build_object('description',a.choice_description,'supplier',a.choice_supplier,'quantity',a.choice_quantity,'actualCents',a.actual_cents) end,
   'differenceCents',case when a.status='decided' then a.actual_cents-a.planned_cents end,
   'variance',case when a.status<>'decided' then null when a.actual_cents>a.planned_cents then 'over' when a.actual_cents<a.planned_cents then 'under' else 'equal' end) order by a.position),'[]'::jsonb) into items
  from public.pro_work_allowances a where a.owner_id=owner and a.work_id=wid and not a.archived;
 totals:=public.pro_work_allowance_totals(owner,wid);
 return jsonb_build_object('visible',true,'items',items,'totals',jsonb_build_object('plannedCents',totals->'plannedCents','actualCents',totals->'actualCents',
  'decidedPlannedCents',totals->'decidedPlannedCents','differenceCents',totals->'differenceCents','pendingCount',totals->'pendingCount','decidedCount',totals->'decidedCount'));
end $$;
create or replace function public.pro_work_allowances_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;aid uuid;rid uuid;rev integer;keys text[];expected text[];receipt public.pro_work_allowance_actions;r public.pro_work_allowances;
 before_json jsonb;after_json jsonb;result jsonb;v_name text;v_category text;v_notes text;v_due date;v_planned numeric;v_desc text;v_supplier text;v_qty numeric;v_actual numeric;v_change uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid allowance' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'create' then array['action','actionId','category','dueDate','id','name','notes','plannedCents','workId']
  when 'update' then array['action','actionId','category','dueDate','id','name','notes','plannedCents','revision','workId']
  when 'decide' then array['action','actionId','actualCents','choiceDescription','id','quantity','revision','supplier','workId']
  when 'link_change' then array['action','actionId','changeId','id','revision','workId']
  when 'reopen' then array['action','actionId','id','revision','workId'] when 'archive' then array['action','actionId','id','revision','workId'] when 'restore' then array['action','actionId','id','revision','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid allowance fields' using errcode='22023';end if;
 if act<>'create' and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'id')::uuid;rev:=case when act<>'create' then (p_input->>'revision')::integer end;
 if length(wid) not between 1 and 160 then raise exception 'Invalid allowance identity' using errcode='22023';end if;
 if act in('create','update') then
  if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'category') not in('string','null') or jsonb_typeof(p_input->'notes') not in('string','null')
   or jsonb_typeof(p_input->'dueDate') not in('string','null') or jsonb_typeof(p_input->'plannedCents') is distinct from 'number' then raise exception 'Invalid allowance fields' using errcode='22023';end if;
  v_name:=btrim(p_input->>'name');v_category:=nullif(btrim(coalesce(p_input->>'category','')),'');v_notes:=nullif(btrim(coalesce(p_input->>'notes','')),'');
  v_planned:=(p_input->>'plannedCents')::numeric;
  if length(v_name) not between 1 and 160 or length(v_category)>80 or length(v_notes)>1000 or v_planned<>round(v_planned) or v_planned not between 0 and 10000000000 then raise exception 'Invalid allowance values' using errcode='22023';end if;
  if p_input->>'dueDate' is not null then
   if not (p_input->>'dueDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid due date' using errcode='22023';end if;
   v_due:=(p_input->>'dueDate')::date;if to_char(v_due,'YYYY-MM-DD')<>p_input->>'dueDate' then raise exception 'Invalid due date' using errcode='22023';end if;
  end if;
 elsif act='decide' then
  if jsonb_typeof(p_input->'choiceDescription') is distinct from 'string' or jsonb_typeof(p_input->'supplier') not in('string','null') or jsonb_typeof(p_input->'quantity') is distinct from 'number'
   or jsonb_typeof(p_input->'actualCents') is distinct from 'number' then raise exception 'Invalid choice fields' using errcode='22023';end if;
  v_desc:=btrim(p_input->>'choiceDescription');v_supplier:=nullif(btrim(coalesce(p_input->>'supplier','')),'');v_qty:=(p_input->>'quantity')::numeric;v_actual:=(p_input->>'actualCents')::numeric;
  if length(v_desc) not between 1 and 300 or length(v_supplier)>160 or v_qty<>round(v_qty,2) or v_qty not between 0.01 and 1000000 or v_actual<>round(v_actual) or v_actual not between 0 and 10000000000 then raise exception 'Invalid choice values' using errcode='22023';end if;
 elsif act='link_change' then
  if jsonb_typeof(p_input->'changeId') is distinct from 'string' then raise exception 'Invalid change link' using errcode='22023';end if;
  v_change:=(p_input->>'changeId')::uuid;
 end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-allowance-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_allowance_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-allowance:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if act='create' then
  if exists(select 1 from public.pro_work_allowances where id=rid) then raise exception 'Allowance id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_work_allowances where owner_id=p_actor and work_id=wid)>=200 then raise exception 'Allowance limit' using errcode='54000';end if;
  before_json:=null;
  insert into public.pro_work_allowances(owner_id,id,work_id,name,category,planned_cents,due_date,notes)
   values(p_actor,rid,wid,v_name,v_category,v_planned::bigint,v_due,v_notes) returning * into r;
 else
  select * into r from public.pro_work_allowances where owner_id=p_actor and id=rid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if r.revision<>rev then raise exception 'Allowance changed' using errcode='40001';end if;
  before_json:=public.pro_work_allowance_json(r);
  if act='update' then
   if r.archived or r.status='decided' then raise exception 'Reopen or restore before editing' using errcode='22023';end if;
   if r.name=v_name and r.category is not distinct from v_category and r.planned_cents=v_planned::bigint and r.due_date is not distinct from v_due and r.notes is not distinct from v_notes then raise exception 'No allowance changes' using errcode='22023';end if;
   update public.pro_work_allowances set name=v_name,category=v_category,planned_cents=v_planned::bigint,due_date=v_due,notes=v_notes,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='decide' then
   if r.archived or r.status='decided' then raise exception 'Allowance already defined' using errcode='22023';end if;
   update public.pro_work_allowances set status='decided',choice_description=v_desc,choice_supplier=v_supplier,choice_quantity=v_qty,actual_cents=v_actual::bigint,decided_at=now(),change_id=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='reopen' then
   if r.archived or r.status<>'decided' then raise exception 'Only defined allowances can be reopened' using errcode='22023';end if;
   -- The previous choice stays in the immutable history (before_item).
   update public.pro_work_allowances set status='reopened',choice_description=null,choice_supplier=null,choice_quantity=null,actual_cents=null,decided_at=null,change_id=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='archive' then
   if r.archived then raise exception 'Already archived' using errcode='22023';end if;
   update public.pro_work_allowances set archived=true,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='restore' then
   if not r.archived then raise exception 'Not archived' using errcode='22023';end if;
   update public.pro_work_allowances set archived=false,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='link_change' then
   if r.archived or r.status<>'decided' or r.change_id is not null or r.actual_cents<=r.planned_cents then raise exception 'Nothing to link' using errcode='22023';end if;
   -- Only a real proposal of this same job for exactly this positive difference.
   if not exists(select 1 from public.pro_work_changes c where c.owner_id=p_actor and c.id=v_change and c.work_id=wid and c.delta_cents=r.actual_cents-r.planned_cents) then raise exception 'Unknown change' using errcode='22023';end if;
   update public.pro_work_allowances set change_id=v_change,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  end if;
 end if;
 after_json:=public.pro_work_allowance_json(r);result:=jsonb_build_object('item',after_json);
 insert into public.pro_work_allowance_history(owner_id,work_id,allowance_id,action_id,action,before_item,after_item) values(p_actor,wid,rid,aid,act,before_json,after_json);
 insert into public.pro_work_allowance_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_allowance_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Allowance history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_allowance_history_immutable on public.pro_work_allowance_history;
create trigger pro_work_allowance_history_immutable before update on public.pro_work_allowance_history for each row execute function public.pro_work_allowance_immutable();
drop trigger if exists pro_work_allowance_action_immutable on public.pro_work_allowance_actions;
create trigger pro_work_allowance_action_immutable before update on public.pro_work_allowance_actions for each row execute function public.pro_work_allowance_immutable();
alter table public.pro_work_allowances enable row level security;
alter table public.pro_work_allowance_history enable row level security;
alter table public.pro_work_allowance_actions enable row level security;
revoke all on public.pro_work_allowances,public.pro_work_allowance_history,public.pro_work_allowance_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_allowances,public.pro_work_allowance_history,public.pro_work_allowance_actions to service_role;
grant usage,select on sequence public.pro_work_allowances_position_seq to service_role;
revoke all on function public.pro_work_allowance_today(),public.pro_work_allowance_json(public.pro_work_allowances),public.pro_work_allowance_totals(uuid,text),public.pro_work_allowances_read(uuid,text),public.pro_work_allowances_client_read(uuid,uuid),public.pro_work_allowances_mutate(uuid,jsonb),public.pro_work_allowance_immutable() from public,anon,authenticated;
grant execute on function public.pro_work_allowance_today(),public.pro_work_allowance_json(public.pro_work_allowances),public.pro_work_allowance_totals(uuid,text),public.pro_work_allowances_read(uuid,text),public.pro_work_allowances_client_read(uuid,uuid),public.pro_work_allowances_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== selections-local.sql =====
-- LOCAL PRO ONLY. Selecciones por área con aprobación del cliente (family 62 of the
-- parity register: selection boards + selections tracker). Per job (pro_work):
-- areas → items to choose → options. The owner publishes an item explicitly; the
-- linked customer (confirmed/completed request, section turned on in the customer
-- view) approves one option or asks for changes with a comment.
-- Amounts are CRC céntimos (bigint), like allowances. Option images reuse the
-- existing private job files (pro_work_files, bucket pro-work-files); no new bucket.
-- Nothing here sends notifications, charges, invoices or calls external services.
-- An optional allowance link only stores the id: applying the approved total to the
-- allowance is an explicit owner action through the allowances API.
begin;
create table if not exists public.pro_work_selection_areas(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,
 position bigint generated always as identity,
 name text not null check(length(btrim(name)) between 1 and 80),
 archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create unique index if not exists pro_work_selection_area_global_id on public.pro_work_selection_areas(id);
create index if not exists pro_work_selection_area_page on public.pro_work_selection_areas(owner_id,work_id,position);
create table if not exists public.pro_work_selection_items(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,area_id uuid not null,
 position bigint generated always as identity,
 name text not null check(length(btrim(name)) between 1 and 160),
 due_date date,notes text check(notes is null or length(btrim(notes)) between 1 and 1000),
 status text not null default 'open' check(status in('open','approved','changes_requested')),
 published boolean not null default false,published_at timestamptz,
 approved_option_id uuid,approved_at timestamptz,
 client_comment text check(client_comment is null or length(btrim(client_comment)) between 1 and 1000),changes_requested_at timestamptz,
 recommended_option_id uuid,allowance_id uuid,
 archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,area_id) references public.pro_work_selection_areas(owner_id,id) on delete cascade,
 foreign key(owner_id,allowance_id) references public.pro_work_allowances(owner_id,id) on delete set null(allowance_id),
 check((status='approved')=(approved_option_id is not null and approved_at is not null)),
 check((status='changes_requested')=(client_comment is not null and changes_requested_at is not null)),
 check(published=(published_at is not null))
);
create unique index if not exists pro_work_selection_item_global_id on public.pro_work_selection_items(id);
create index if not exists pro_work_selection_item_page on public.pro_work_selection_items(owner_id,work_id,position);
create table if not exists public.pro_work_selection_options(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,item_id uuid not null,
 position bigint generated always as identity,
 name text not null check(length(btrim(name)) between 1 and 160),
 brand text check(brand is null or length(btrim(brand)) between 1 and 160),
 url text check(url is null or (length(url)<=500 and url~'^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$')),
 quantity numeric(12,2) not null check(quantity between 0.01 and 1000000),
 unit_cents bigint not null check(unit_cents between 0 and 10000000000),
 total_cents bigint generated always as (round(quantity*unit_cents)::bigint) stored,
 client_notes text check(client_notes is null or length(btrim(client_notes)) between 1 and 1000),
 image_file_id uuid,
 archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,item_id) references public.pro_work_selection_items(owner_id,id) on delete cascade,
 -- Reuses the private job files: only an image of this same job can be attached.
 foreign key(owner_id,work_id,image_file_id) references public.pro_work_files(owner_id,work_id,id) on delete cascade,
 check(total_cents<=10000000000)
);
create unique index if not exists pro_work_selection_option_global_id on public.pro_work_selection_options(id);
create index if not exists pro_work_selection_option_page on public.pro_work_selection_options(owner_id,item_id,position);
create table if not exists public.pro_work_selection_history(
 owner_id uuid not null,work_id text not null,action_id uuid not null,actor_id uuid not null,side text not null check(side in('owner','client')),
 action text not null check(action in('area_create','area_update','area_archive','area_restore','item_create','item_update','option_add','option_update','option_remove','recommend','publish','unpublish','reopen','archive','restore','approve','request_changes')),
 target_kind text not null check(target_kind in('area','item')),target_id uuid not null,
 before_value jsonb,after_value jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_selection_history_page on public.pro_work_selection_history(owner_id,work_id,at desc);
create table if not exists public.pro_work_selection_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
-- Costa Rica calendar day (UTC-6, no DST) for overdue decisions.
create or replace function public.pro_work_selection_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (now() at time zone 'America/Costa_Rica')::date $$;
create or replace function public.pro_work_selection_area_json(p_row public.pro_work_selection_areas) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'position',p_row.position,'name',p_row.name,'archived',p_row.archived,'revision',p_row.revision,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at);
$$;
create or replace function public.pro_work_selection_option_json(p_row public.pro_work_selection_options) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'position',p_row.position,'name',p_row.name,'brand',p_row.brand,'url',p_row.url,'quantity',p_row.quantity,
  'unitCents',p_row.unit_cents,'totalCents',p_row.total_cents,'clientNotes',p_row.client_notes,'imageFileId',p_row.image_file_id);
$$;
-- Derived state: archived, approved, changes_requested, no_options, pending_client (published) or draft.
create or replace function public.pro_work_selection_state(p_row public.pro_work_selection_items) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_row.archived then 'archived' when p_row.status<>'open' then p_row.status
  when not exists(select 1 from public.pro_work_selection_options o where o.owner_id=p_row.owner_id and o.item_id=p_row.id and not o.archived) then 'no_options'
  when p_row.published then 'pending_client' else 'draft' end;
$$;
create or replace function public.pro_work_selection_item_json(p_row public.pro_work_selection_items) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'areaId',p_row.area_id,'position',p_row.position,'name',p_row.name,'dueDate',p_row.due_date,'notes',p_row.notes,
  'status',p_row.status,'state',public.pro_work_selection_state(p_row),'published',p_row.published,'publishedAt',p_row.published_at,
  'approvedOptionId',p_row.approved_option_id,'approvedAt',p_row.approved_at,'clientComment',p_row.client_comment,'changesRequestedAt',p_row.changes_requested_at,
  'recommendedOptionId',p_row.recommended_option_id,'allowanceId',p_row.allowance_id,'archived',p_row.archived,
  'overdue',p_row.status<>'approved' and not p_row.archived and p_row.due_date is not null and p_row.due_date<public.pro_work_selection_today(),
  'options',coalesce((select jsonb_agg(public.pro_work_selection_option_json(o) order by o.position) from public.pro_work_selection_options o where o.owner_id=p_row.owner_id and o.item_id=p_row.id and not o.archived),'[]'::jsonb),
  'revision',p_row.revision,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at);
$$;
create or replace function public.pro_work_selections_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare areas jsonb;items jsonb;hist jsonb;allowances jsonb;visible boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid selection query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select coalesce(jsonb_agg(public.pro_work_selection_area_json(a) order by a.archived,a.position),'[]'::jsonb) into areas from public.pro_work_selection_areas a where a.owner_id=p_actor and a.work_id=p_work;
 select coalesce(jsonb_agg(public.pro_work_selection_item_json(i) order by i.archived,i.position),'[]'::jsonb) into items from public.pro_work_selection_items i where i.owner_id=p_actor and i.work_id=p_work;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'category',a.category,'status',a.status,'plannedCents',a.planned_cents,'actualCents',a.actual_cents,'revision',a.revision) order by a.position),'[]'::jsonb) into allowances
  from public.pro_work_allowances a where a.owner_id=p_actor and a.work_id=p_work and not a.archived;
 select coalesce(show_selections,false) into visible from public.pro_client_dashboards where owner_id=p_actor and work_id=p_work;
 select coalesce(jsonb_agg(x.content order by x.at desc,x.action_id),'[]'::jsonb) into hist from (
  select h.at,h.action_id,jsonb_build_object('actionId',h.action_id,'side',h.side,'action',h.action,'targetKind',h.target_kind,'targetId',h.target_id,'at',h.at,'before',h.before_value,'after',h.after_value) as content
  from public.pro_work_selection_history h where h.owner_id=p_actor and h.work_id=p_work order by h.at desc,h.action_id limit 100
 ) x;
 return jsonb_build_object('workId',p_work,'today',public.pro_work_selection_today(),'clientVisible',coalesce(visible,false),'areas',areas,'items',items,'allowances',allowances,'history',hist);
end $$;
-- Linked customer context: request of this actor, with a job, confirmed/completed,
-- and the section turned on in the customer view. Returns null owner when not visible.
create or replace function public.pro_work_selection_client_context(p_actor uuid,p_request uuid,out owner uuid,out wid text,out found_request boolean,out visible boolean)
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare req_status text;enabled boolean;
begin
 found_request:=false;visible:=false;
 select r.owner_id,r.work_id,r.status into owner,wid,req_status from public.pro_appointment_requests r where r.id=p_request and r.client_user_id=p_actor and r.work_id is not null;
 if not found then owner:=null;wid:=null;return;end if;
 found_request:=true;
 select coalesce(d.show_selections,false) into enabled from public.pro_client_dashboards d where d.owner_id=owner and d.work_id=wid;
 visible:=req_status in('confirmed','completed') and coalesce(enabled,false);
end $$;
-- Customer view of one published item: no internal notes, allowance link, history or image file ids.
create or replace function public.pro_work_selection_client_item_json(p_row public.pro_work_selection_items) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'areaId',p_row.area_id,'name',p_row.name,'dueDate',p_row.due_date,'state',public.pro_work_selection_state(p_row),
  'approvedOptionId',p_row.approved_option_id,'approvedAt',p_row.approved_at,'clientComment',p_row.client_comment,'recommendedOptionId',p_row.recommended_option_id,'revision',p_row.revision,
  'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'brand',o.brand,'url',o.url,'quantity',o.quantity,'unitCents',o.unit_cents,'totalCents',o.total_cents,
   'clientNotes',o.client_notes,'hasImage',o.image_file_id is not null) order by o.position) from public.pro_work_selection_options o where o.owner_id=p_row.owner_id and o.item_id=p_row.id and not o.archived),'[]'::jsonb));
$$;
create or replace function public.pro_work_selections_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx record;areas jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into ctx from public.pro_work_selection_client_context(p_actor,p_request);
 if not ctx.found_request then return null;end if;
 if not ctx.visible then return jsonb_build_object('visible',false);end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'items',x.items) order by a.position),'[]'::jsonb) into areas
  from public.pro_work_selection_areas a
  join lateral (select jsonb_agg(public.pro_work_selection_client_item_json(i) order by i.position) as items from public.pro_work_selection_items i
   where i.owner_id=a.owner_id and i.area_id=a.id and i.published and not i.archived) x on x.items is not null
  where a.owner_id=ctx.owner and a.work_id=ctx.wid and not a.archived;
 return jsonb_build_object('visible',true,'today',public.pro_work_selection_today(),'areas',areas);
end $$;
-- Image access for an option: the owner, or the linked customer while the item is
-- published and visible to them. Returns storage metadata of the reused job file.
create or replace function public.pro_work_selection_image(p_actor uuid,p_option uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare o public.pro_work_selection_options;i public.pro_work_selection_items;f public.pro_work_files;allowed boolean:=false;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into o from public.pro_work_selection_options where id=p_option and not archived and image_file_id is not null;
 if not found then return null;end if;
 select * into i from public.pro_work_selection_items where owner_id=o.owner_id and id=o.item_id;
 if o.owner_id=p_actor then
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
  allowed:=true;
 else
  allowed:=i.published and not i.archived
   and exists(select 1 from public.pro_work_selection_areas a where a.owner_id=i.owner_id and a.id=i.area_id and not a.archived)
   and exists(select 1 from public.pro_appointment_requests r join public.pro_client_dashboards d on d.owner_id=r.owner_id and d.work_id=r.work_id
    where r.owner_id=o.owner_id and r.work_id=o.work_id and r.client_user_id=p_actor and r.status in('confirmed','completed') and d.show_selections);
 end if;
 if not allowed then return null;end if;
 select * into f from public.pro_work_files where owner_id=o.owner_id and work_id=o.work_id and id=o.image_file_id and ready and mime_type='image/jpeg';
 if not found then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;
create or replace function public.pro_work_selection_text(p_value jsonb,p_max integer) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare v text;
begin
 if jsonb_typeof(p_value)='null' then return null;end if;
 if jsonb_typeof(p_value) is distinct from 'string' then raise exception 'Invalid selection text' using errcode='22023';end if;
 v:=nullif(btrim(p_value#>>'{}'),'');
 if v is not null and length(v)>p_max then raise exception 'Selection text too long' using errcode='22023';end if;
 return v;
end $$;
create or replace function public.pro_work_selections_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;aid uuid;tid uuid;rev integer;keys text[];expected text[];receipt public.pro_work_selection_actions;
 area public.pro_work_selection_areas;item public.pro_work_selection_items;opt public.pro_work_selection_options;
 before_json jsonb;after_json jsonb;result jsonb;kind text;
 v_name text;v_notes text;v_due date;v_area uuid;v_allowance uuid;v_option uuid;v_brand text;v_url text;v_qty numeric;v_unit numeric;v_client text;v_image uuid;
 option_keys text[]:=array['action','actionId','brand','clientNotes','id','imageFileId','name','optionId','quantity','revision','unitCents','url','workId'];
 item_keys text[]:=array['action','actionId','allowanceId','areaId','dueDate','id','name','notes','workId'];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid selection' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'area_create' then array['action','actionId','id','name','workId']
  when 'area_update' then array['action','actionId','id','name','revision','workId']
  when 'area_archive' then array['action','actionId','id','revision','workId'] when 'area_restore' then array['action','actionId','id','revision','workId']
  when 'item_create' then item_keys
  when 'item_update' then array['action','actionId','allowanceId','areaId','dueDate','id','name','notes','revision','workId']
  when 'option_add' then option_keys when 'option_update' then option_keys
  when 'option_remove' then array['action','actionId','id','optionId','revision','workId']
  when 'recommend' then array['action','actionId','id','optionId','revision','workId']
  when 'publish' then array['action','actionId','id','revision','workId'] when 'unpublish' then array['action','actionId','id','revision','workId']
  when 'reopen' then array['action','actionId','id','revision','workId'] when 'archive' then array['action','actionId','id','revision','workId']
  when 'restore' then array['action','actionId','id','revision','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid selection fields' using errcode='22023';end if;
 if act not in('area_create','item_create') and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;tid:=(p_input->>'id')::uuid;rev:=case when act not in('area_create','item_create') then (p_input->>'revision')::integer end;
 if length(wid) not between 1 and 160 then raise exception 'Invalid selection identity' using errcode='22023';end if;
 kind:=case when act like 'area_%' then 'area' else 'item' end;
 if act in('area_create','area_update') then
  v_name:=public.pro_work_selection_text(p_input->'name',80);if v_name is null then raise exception 'Invalid area name' using errcode='22023';end if;
 elsif act in('item_create','item_update') then
  v_name:=public.pro_work_selection_text(p_input->'name',160);v_notes:=public.pro_work_selection_text(p_input->'notes',1000);
  if v_name is null or jsonb_typeof(p_input->'areaId') is distinct from 'string' or jsonb_typeof(p_input->'dueDate') not in('string','null') or jsonb_typeof(p_input->'allowanceId') not in('string','null') then raise exception 'Invalid item fields' using errcode='22023';end if;
  v_area:=(p_input->>'areaId')::uuid;v_allowance:=(p_input->>'allowanceId')::uuid;
  if p_input->>'dueDate' is not null then
   if not (p_input->>'dueDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid due date' using errcode='22023';end if;
   v_due:=(p_input->>'dueDate')::date;if to_char(v_due,'YYYY-MM-DD')<>p_input->>'dueDate' then raise exception 'Invalid due date' using errcode='22023';end if;
  end if;
 elsif act in('option_add','option_update') then
  v_name:=public.pro_work_selection_text(p_input->'name',160);v_brand:=public.pro_work_selection_text(p_input->'brand',160);
  v_url:=public.pro_work_selection_text(p_input->'url',500);v_client:=public.pro_work_selection_text(p_input->'clientNotes',1000);
  if v_name is null or jsonb_typeof(p_input->'optionId') is distinct from 'string' or jsonb_typeof(p_input->'quantity') is distinct from 'number' or jsonb_typeof(p_input->'unitCents') is distinct from 'number'
   or jsonb_typeof(p_input->'imageFileId') not in('string','null') then raise exception 'Invalid option fields' using errcode='22023';end if;
  v_option:=(p_input->>'optionId')::uuid;v_image:=(p_input->>'imageFileId')::uuid;v_qty:=(p_input->>'quantity')::numeric;v_unit:=(p_input->>'unitCents')::numeric;
  if v_qty<>round(v_qty,2) or v_qty not between 0.01 and 1000000 or v_unit<>round(v_unit) or v_unit not between 0 and 10000000000 or round(v_qty*v_unit)>10000000000 then raise exception 'Invalid option amounts' using errcode='22023';end if;
  if v_url is not null and not (length(v_url)<=500 and v_url~'^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$') then raise exception 'Invalid option link' using errcode='22023';end if;
 elsif act='option_remove' then
  if jsonb_typeof(p_input->'optionId') is distinct from 'string' then raise exception 'Invalid option' using errcode='22023';end if;v_option:=(p_input->>'optionId')::uuid;
 elsif act='recommend' then
  if jsonb_typeof(p_input->'optionId') not in('string','null') then raise exception 'Invalid option' using errcode='22023';end if;v_option:=(p_input->>'optionId')::uuid;
 end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_selection_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if act in('item_create','item_update') then
  if not exists(select 1 from public.pro_work_selection_areas where owner_id=p_actor and id=v_area and work_id=wid and not archived) then raise exception 'Unknown area' using errcode='22023';end if;
  if v_allowance is not null and not exists(select 1 from public.pro_work_allowances where owner_id=p_actor and id=v_allowance and work_id=wid and not archived) then raise exception 'Unknown allowance' using errcode='22023';end if;
 end if;
 if act='area_create' then
  if exists(select 1 from public.pro_work_selection_areas where id=tid) then raise exception 'Area id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_work_selection_areas where owner_id=p_actor and work_id=wid)>=50 then raise exception 'Area limit' using errcode='54000';end if;
  insert into public.pro_work_selection_areas(owner_id,id,work_id,name) values(p_actor,tid,wid,v_name) returning * into area;
  before_json:=null;after_json:=public.pro_work_selection_area_json(area);
 elsif kind='area' then
  select * into area from public.pro_work_selection_areas where owner_id=p_actor and id=tid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if area.revision<>rev then raise exception 'Area changed' using errcode='40001';end if;
  before_json:=public.pro_work_selection_area_json(area);
  if act='area_update' then
   if area.archived then raise exception 'Restore before editing' using errcode='22023';end if;
   if area.name=v_name then raise exception 'No area changes' using errcode='22023';end if;
   update public.pro_work_selection_areas set name=v_name,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into area;
  elsif act='area_archive' then
   if area.archived then raise exception 'Already archived' using errcode='22023';end if;
   -- An area is archived only once its items are archived or moved, so nothing published disappears silently.
   if exists(select 1 from public.pro_work_selection_items where owner_id=p_actor and area_id=tid and not archived) then raise exception 'Area has active items' using errcode='22023';end if;
   update public.pro_work_selection_areas set archived=true,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into area;
  else
   if not area.archived then raise exception 'Not archived' using errcode='22023';end if;
   update public.pro_work_selection_areas set archived=false,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into area;
  end if;
  after_json:=public.pro_work_selection_area_json(area);
 elsif act='item_create' then
  if exists(select 1 from public.pro_work_selection_items where id=tid) then raise exception 'Item id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_work_selection_items where owner_id=p_actor and work_id=wid)>=300 then raise exception 'Item limit' using errcode='54000';end if;
  insert into public.pro_work_selection_items(owner_id,id,work_id,area_id,name,due_date,notes,allowance_id) values(p_actor,tid,wid,v_area,v_name,v_due,v_notes,v_allowance) returning * into item;
  before_json:=null;after_json:=public.pro_work_selection_item_json(item);
 else
  select * into item from public.pro_work_selection_items where owner_id=p_actor and id=tid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if item.revision<>rev then raise exception 'Item changed' using errcode='40001';end if;
  before_json:=public.pro_work_selection_item_json(item);
  if item.archived and act<>'restore' then raise exception 'Restore before editing' using errcode='22023';end if;
  if act='item_update' then
   if item.area_id=v_area and item.name=v_name and item.due_date is not distinct from v_due and item.notes is not distinct from v_notes and item.allowance_id is not distinct from v_allowance then raise exception 'No item changes' using errcode='22023';end if;
   update public.pro_work_selection_items set area_id=v_area,name=v_name,due_date=v_due,notes=v_notes,allowance_id=v_allowance,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act in('option_add','option_update','option_remove','recommend') then
   -- An approved item is locked: reopen it first (the approval stays in the history).
   if item.status='approved' then raise exception 'Reopen before changing options' using errcode='22023';end if;
   if act='option_add' then
    if exists(select 1 from public.pro_work_selection_options where id=v_option) then raise exception 'Option id already used' using errcode='23505';end if;
    if (select count(*) from public.pro_work_selection_options where owner_id=p_actor and item_id=tid and not archived)>=12 or (select count(*) from public.pro_work_selection_options where owner_id=p_actor and item_id=tid)>=60 then raise exception 'Option limit' using errcode='54000';end if;
    if v_image is not null and not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=v_image and ready and mime_type='image/jpeg') then raise exception 'Unknown image' using errcode='22023';end if;
    insert into public.pro_work_selection_options(owner_id,id,work_id,item_id,name,brand,url,quantity,unit_cents,client_notes,image_file_id) values(p_actor,v_option,wid,tid,v_name,v_brand,v_url,v_qty,v_unit::bigint,v_client,v_image);
   elsif act='option_update' then
    select * into opt from public.pro_work_selection_options where owner_id=p_actor and id=v_option and item_id=tid and not archived for update;
    if not found then raise exception 'Unknown option' using errcode='22023';end if;
    if v_image is not null and v_image is distinct from opt.image_file_id and not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=v_image and ready and mime_type='image/jpeg') then raise exception 'Unknown image' using errcode='22023';end if;
    if opt.name=v_name and opt.brand is not distinct from v_brand and opt.url is not distinct from v_url and opt.quantity=v_qty and opt.unit_cents=v_unit::bigint and opt.client_notes is not distinct from v_client and opt.image_file_id is not distinct from v_image then raise exception 'No option changes' using errcode='22023';end if;
    update public.pro_work_selection_options set name=v_name,brand=v_brand,url=v_url,quantity=v_qty,unit_cents=v_unit::bigint,client_notes=v_client,image_file_id=v_image,updated_at=now() where owner_id=p_actor and id=v_option;
   elsif act='option_remove' then
    select * into opt from public.pro_work_selection_options where owner_id=p_actor and id=v_option and item_id=tid and not archived for update;
    if not found then raise exception 'Unknown option' using errcode='22023';end if;
    if item.published and (select count(*) from public.pro_work_selection_options where owner_id=p_actor and item_id=tid and not archived)=1 then raise exception 'Unpublish before removing the last option' using errcode='22023';end if;
    -- Soft removal: the option stays in the history snapshots.
    update public.pro_work_selection_options set archived=true,updated_at=now() where owner_id=p_actor and id=v_option;
    if item.recommended_option_id=v_option then update public.pro_work_selection_items set recommended_option_id=null where owner_id=p_actor and id=tid;end if;
   else
    if v_option is not null and not exists(select 1 from public.pro_work_selection_options where owner_id=p_actor and id=v_option and item_id=tid and not archived) then raise exception 'Unknown option' using errcode='22023';end if;
    if item.recommended_option_id is not distinct from v_option then raise exception 'No recommendation change' using errcode='22023';end if;
    update public.pro_work_selection_items set recommended_option_id=v_option where owner_id=p_actor and id=tid;
   end if;
   update public.pro_work_selection_items set revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act='publish' then
   if item.published then raise exception 'Already published' using errcode='22023';end if;
   if not exists(select 1 from public.pro_work_selection_options where owner_id=p_actor and item_id=tid and not archived) then raise exception 'Add an option before publishing' using errcode='22023';end if;
   update public.pro_work_selection_items set published=true,published_at=now(),revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act='unpublish' then
   if not item.published then raise exception 'Not published' using errcode='22023';end if;
   update public.pro_work_selection_items set published=false,published_at=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act='reopen' then
   -- Approved or with changes requested → open again (pending the customer if still published).
   if item.status='open' then raise exception 'Nothing to reopen' using errcode='22023';end if;
   update public.pro_work_selection_items set status='open',approved_option_id=null,approved_at=null,client_comment=null,changes_requested_at=null,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act='archive' then
   update public.pro_work_selection_items set archived=true,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  elsif act='restore' then
   if not item.archived then raise exception 'Not archived' using errcode='22023';end if;
   if not exists(select 1 from public.pro_work_selection_areas where owner_id=p_actor and id=item.area_id and not archived) then raise exception 'Restore the area first' using errcode='22023';end if;
   update public.pro_work_selection_items set archived=false,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into item;
  end if;
  after_json:=public.pro_work_selection_item_json(item);
 end if;
 result:=jsonb_build_object(kind,after_json);
 insert into public.pro_work_selection_history(owner_id,work_id,action_id,actor_id,side,action,target_kind,target_id,before_value,after_value) values(p_actor,wid,aid,p_actor,'owner',act,kind,tid,before_json,after_json);
 insert into public.pro_work_selection_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
-- Customer decision on a published item: approve one option or ask for changes with a comment.
create or replace function public.pro_work_selections_client_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;rid uuid;tid uuid;rev integer;keys text[];receipt public.pro_work_selection_actions;ctx record;item public.pro_work_selection_items;
 before_json jsonb;after_json jsonb;result jsonb;v_option uuid;v_comment text;expected text[];
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid decision' using errcode='22023';end if;
 act:=p_input->>'action';
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 expected:=case act when 'approve' then array['action','actionId','id','optionId','requestId','revision'] when 'request_changes' then array['action','actionId','comment','id','requestId','revision'] end;
 if expected is null or keys is distinct from expected
  or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string'
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid decision fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'requestId')::uuid;tid:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;
 if act='approve' then
  if jsonb_typeof(p_input->'optionId') is distinct from 'string' then raise exception 'Invalid option' using errcode='22023';end if;v_option:=(p_input->>'optionId')::uuid;
 else
  v_comment:=public.pro_work_selection_text(p_input->'comment',1000);if v_comment is null then raise exception 'Comment required' using errcode='22023';end if;
 end if;
 select * into ctx from public.pro_work_selection_client_context(p_actor,rid);
 if not ctx.found_request or not ctx.visible then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_selection_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-selection:'||ctx.owner::text||':'||ctx.wid,0));
 select * into item from public.pro_work_selection_items where owner_id=ctx.owner and work_id=ctx.wid and id=tid for update;
 -- An unpublished, archived or unknown item does not exist for the customer.
 if not found or not item.published or item.archived or not exists(select 1 from public.pro_work_selection_areas a where a.owner_id=item.owner_id and a.id=item.area_id and not a.archived) then raise exception 'Forbidden' using errcode='42501';end if;
 if item.revision<>rev then raise exception 'Item changed' using errcode='40001';end if;
 before_json:=public.pro_work_selection_item_json(item);
 if act='approve' then
  if item.status='approved' then raise exception 'Already approved' using errcode='22023';end if;
  if not exists(select 1 from public.pro_work_selection_options where owner_id=item.owner_id and item_id=tid and id=v_option and not archived) then raise exception 'Unknown option' using errcode='22023';end if;
  update public.pro_work_selection_items set status='approved',approved_option_id=v_option,approved_at=now(),client_comment=null,changes_requested_at=null,revision=revision+1,updated_at=now() where owner_id=item.owner_id and id=tid returning * into item;
 else
  if item.status<>'open' then raise exception 'Changes can only be requested on a pending item' using errcode='22023';end if;
  update public.pro_work_selection_items set status='changes_requested',client_comment=v_comment,changes_requested_at=now(),revision=revision+1,updated_at=now() where owner_id=item.owner_id and id=tid returning * into item;
 end if;
 after_json:=public.pro_work_selection_item_json(item);
 result:=jsonb_build_object('item',public.pro_work_selection_client_item_json(item));
 insert into public.pro_work_selection_history(owner_id,work_id,action_id,actor_id,side,action,target_kind,target_id,before_value,after_value) values(item.owner_id,item.work_id,aid,p_actor,'client',act,'item',tid,before_json,after_json);
 insert into public.pro_work_selection_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
create or replace function public.pro_work_selection_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Selection history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_selection_history_immutable on public.pro_work_selection_history;
create trigger pro_work_selection_history_immutable before update on public.pro_work_selection_history for each row execute function public.pro_work_selection_immutable();
drop trigger if exists pro_work_selection_action_immutable on public.pro_work_selection_actions;
create trigger pro_work_selection_action_immutable before update on public.pro_work_selection_actions for each row execute function public.pro_work_selection_immutable();
alter table public.pro_work_selection_areas enable row level security;
alter table public.pro_work_selection_items enable row level security;
alter table public.pro_work_selection_options enable row level security;
alter table public.pro_work_selection_history enable row level security;
alter table public.pro_work_selection_actions enable row level security;
revoke all on public.pro_work_selection_areas,public.pro_work_selection_items,public.pro_work_selection_options,public.pro_work_selection_history,public.pro_work_selection_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_selection_areas,public.pro_work_selection_items,public.pro_work_selection_options,public.pro_work_selection_history,public.pro_work_selection_actions to service_role;
grant usage,select on sequence public.pro_work_selection_areas_position_seq,public.pro_work_selection_items_position_seq,public.pro_work_selection_options_position_seq to service_role;
revoke all on function public.pro_work_selection_today(),public.pro_work_selection_area_json(public.pro_work_selection_areas),public.pro_work_selection_option_json(public.pro_work_selection_options),
 public.pro_work_selection_state(public.pro_work_selection_items),public.pro_work_selection_item_json(public.pro_work_selection_items),public.pro_work_selections_read(uuid,text),
 public.pro_work_selection_client_context(uuid,uuid),public.pro_work_selection_client_item_json(public.pro_work_selection_items),public.pro_work_selections_client_read(uuid,uuid),
 public.pro_work_selection_image(uuid,uuid),public.pro_work_selection_text(jsonb,integer),public.pro_work_selections_mutate(uuid,jsonb),public.pro_work_selections_client_mutate(uuid,jsonb),
 public.pro_work_selection_immutable() from public,anon,authenticated;
grant execute on function public.pro_work_selection_today(),public.pro_work_selection_area_json(public.pro_work_selection_areas),public.pro_work_selection_option_json(public.pro_work_selection_options),
 public.pro_work_selection_state(public.pro_work_selection_items),public.pro_work_selection_item_json(public.pro_work_selection_items),public.pro_work_selections_read(uuid,text),
 public.pro_work_selection_client_context(uuid,uuid),public.pro_work_selection_client_item_json(public.pro_work_selection_items),public.pro_work_selections_client_read(uuid,uuid),
 public.pro_work_selection_image(uuid,uuid),public.pro_work_selection_text(jsonb,integer),public.pro_work_selections_mutate(uuid,jsonb),public.pro_work_selections_client_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== purchase-orders-local.sql =====
-- LOCAL PRO ONLY. Órdenes de compra por proyecto (families 51, 52 and 54 of the
-- parity register). Owner-private purchase orders per job (pro_work) with a
-- per-account sequential number (OC-0001), supplier from the existing expense
-- suppliers (or a free name), lines with optional budget code / approved
-- selection option / allowance, optional tax per line, per-line receipts and
-- manual supplier payments. Amounts are CRC céntimos (bigint), like work-budget.
-- Nothing here sends e-mail, moves money, creates expenses or invoices.
--
-- Rounding (documented in purchase-orders-local.md): per line,
--   subtotal = round(quantity × unit_cents)          (numeric round, half away from zero)
--   tax      = round(subtotal × tax_rate / 100)
--   total    = subtotal + tax;  order total = Σ line totals.
--
-- Budget: a non-cancelled order is a COMMITMENT, never an actual cost. The budget
-- comparison (pro_purchase_order_budget) shows planned, committed and actual per
-- code and projects each code with greatest(committed, actual) so a later real
-- expense for the same purchase is never added on top of its order.
--
-- Lock order: own action advisory -> own work advisory (same key as nothing else)
-- -> account counter row (create only) -> order row.
begin;
create table if not exists public.pro_purchase_order_counters(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 last_number integer not null default 0 check(last_number between 0 and 999999)
);
create table if not exists public.pro_purchase_orders(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,
 number integer not null check(number between 1 and 999999),
 supplier_id uuid,supplier_name text not null check(length(btrim(supplier_name)) between 1 and 160),
 supplier_contact text check(supplier_contact is null or length(btrim(supplier_contact)) between 1 and 200),
 title text not null check(length(btrim(title)) between 1 and 160),
 issue_date date not null,expected_date date,
 notes text check(notes is null or length(btrim(notes)) between 1 and 2000),
 status text not null default 'draft' check(status in('draft','issued','partial','received','cancelled')),
 issued_at timestamptz,cancelled_at timestamptz,
 cancel_reason text check(cancel_reason is null or length(btrim(cancel_reason)) between 1 and 300),
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,number),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,supplier_id) references public.pro_expense_suppliers(user_id,id),
 check(expected_date is null or expected_date>=issue_date),
 check((status='cancelled')=(cancelled_at is not null))
);
-- Issued-family states carry the issue stamp; a draft has none; a cancelled order may be either.
do $$declare c text;begin
 for c in select conname from pg_constraint where conrelid='public.pro_purchase_orders'::regclass and contype='c' and pg_get_constraintdef(oid) like '%issued_at IS NULL%' and conname<>'pro_purchase_order_issue_stamp' loop
  execute format('alter table public.pro_purchase_orders drop constraint %I',c);
 end loop;
end $$;
alter table public.pro_purchase_orders drop constraint if exists pro_purchase_order_issue_stamp;
alter table public.pro_purchase_orders add constraint pro_purchase_order_issue_stamp check((status='draft' and issued_at is null) or status='cancelled' or (status in('issued','partial','received') and issued_at is not null));
create unique index if not exists pro_purchase_order_global_id on public.pro_purchase_orders(id);
create index if not exists pro_purchase_order_page on public.pro_purchase_orders(owner_id,work_id,number desc);
create table if not exists public.pro_purchase_order_lines(
 owner_id uuid not null,work_id text not null,order_id uuid not null,id uuid not null,
 position smallint not null check(position between 1 and 100),
 description text not null check(length(btrim(description)) between 1 and 300),
 quantity numeric(12,3) not null check(quantity between 0.001 and 1000000),
 unit text not null check(length(btrim(unit)) between 1 and 20),
 unit_cents bigint not null check(unit_cents between 0 and 10000000000),
 tax_rate numeric(5,2) not null default 0 check(tax_rate between 0 and 100),
 subtotal_cents bigint generated always as (round(quantity*unit_cents)::bigint) stored,
 tax_cents bigint generated always as (round(round(quantity*unit_cents)*tax_rate/100)::bigint) stored,
 budget_code_id uuid,selection_option_id uuid,allowance_id uuid,
 primary key(owner_id,id),unique(owner_id,order_id,position),
 foreign key(owner_id,order_id) references public.pro_purchase_orders(owner_id,id) on delete cascade,
 check(subtotal_cents<=10000000000),check(selection_option_id is null or allowance_id is null)
);
-- Optional references: losing the referenced row (account cleanup cascades) only clears the link.
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_lines_owner_id_work_id_budget_code_id_fkey;
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_lines_owner_id_selection_option_id_fkey;
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_lines_owner_id_allowance_id_fkey;
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_line_budget_code;
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_line_selection_option;
alter table public.pro_purchase_order_lines drop constraint if exists pro_purchase_order_line_allowance;
alter table public.pro_purchase_order_lines add constraint pro_purchase_order_line_budget_code foreign key(owner_id,work_id,budget_code_id) references public.pro_work_budget_codes(owner_id,work_id,id) on delete set null(budget_code_id);
alter table public.pro_purchase_order_lines add constraint pro_purchase_order_line_selection_option foreign key(owner_id,selection_option_id) references public.pro_work_selection_options(owner_id,id) on delete set null(selection_option_id);
alter table public.pro_purchase_order_lines add constraint pro_purchase_order_line_allowance foreign key(owner_id,allowance_id) references public.pro_work_allowances(owner_id,id) on delete set null(allowance_id);
create index if not exists pro_purchase_order_lines_order on public.pro_purchase_order_lines(owner_id,order_id,position);
create index if not exists pro_purchase_order_lines_code on public.pro_purchase_order_lines(owner_id,work_id,budget_code_id);
-- One row per received line per receipt action; never updated (no edits, no deletes).
create table if not exists public.pro_purchase_order_receipts(
 owner_id uuid not null,order_id uuid not null,id uuid not null,line_id uuid not null,
 quantity numeric(12,3) not null check(quantity between 0.001 and 1000000),
 received_on date not null,note text check(note is null or length(btrim(note)) between 1 and 300),
 created_at timestamptz not null default now(),
 primary key(owner_id,id,line_id),
 foreign key(owner_id,order_id) references public.pro_purchase_orders(owner_id,id) on delete cascade,
 foreign key(owner_id,line_id) references public.pro_purchase_order_lines(owner_id,id) on delete cascade
);
create index if not exists pro_purchase_order_receipts_order on public.pro_purchase_order_receipts(owner_id,order_id);
-- Manual record of a payment made outside ContrataCR; a reversal is a new row.
create table if not exists public.pro_purchase_order_payments(
 owner_id uuid not null,order_id uuid not null,id uuid not null,
 kind text not null check(kind in('payment','reverse')),payment_id uuid,
 amount_cents bigint not null check(amount_cents between 1 and 10000000000000),
 paid_on date not null,method text not null check(method in('transfer','sinpe','cash','card','check','other')),
 reference text check(reference is null or length(btrim(reference)) between 1 and 160),
 note text check(note is null or length(btrim(note)) between 1 and 300),
 created_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,order_id,id),
 foreign key(owner_id,order_id) references public.pro_purchase_orders(owner_id,id) on delete cascade,
 foreign key(owner_id,order_id,payment_id) references public.pro_purchase_order_payments(owner_id,order_id,id),
 check((kind='payment' and payment_id is null) or (kind='reverse' and payment_id is not null and note is not null))
);
create unique index if not exists pro_purchase_order_one_reverse on public.pro_purchase_order_payments(owner_id,payment_id) where kind='reverse';
create table if not exists public.pro_purchase_order_history(
 owner_id uuid not null,work_id text not null,order_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','issue','receive','pay','reverse_payment','cancel')),
 before_value jsonb,after_value jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,action_id),foreign key(owner_id,order_id) references public.pro_purchase_orders(owner_id,id) on delete cascade
);
create index if not exists pro_purchase_order_history_page on public.pro_purchase_order_history(owner_id,order_id,at desc);
create table if not exists public.pro_purchase_order_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);

-- Costa Rica calendar day (UTC-6, no DST) for overdue and date limits.
create or replace function public.pro_purchase_order_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (now() at time zone 'America/Costa_Rica')::date $$;

create or replace function public.pro_purchase_order_figures(p_owner uuid,p_order uuid,
 out subtotal_cents bigint,out tax_cents bigint,out total_cents bigint,out paid_cents bigint,out line_count integer)
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(l.subtotal_cents),0)::bigint,coalesce(sum(l.tax_cents),0)::bigint,coalesce(sum(l.subtotal_cents+l.tax_cents),0)::bigint,
  (select coalesce(sum(case when p.kind='payment' then p.amount_cents else -p.amount_cents end),0)::bigint from public.pro_purchase_order_payments p where p.owner_id=p_owner and p.order_id=p_order),
  count(l.id)::integer
 from public.pro_purchase_order_lines l where l.owner_id=p_owner and l.order_id=p_order;
$$;

create or replace function public.pro_purchase_order_summary(p_row public.pro_purchase_orders) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'number',p_row.number,'code','OC-'||lpad(p_row.number::text,4,'0'),
  'title',p_row.title,'supplierId',p_row.supplier_id,'supplierName',p_row.supplier_name,'supplierContact',p_row.supplier_contact,
  'status',p_row.status,'issueDate',p_row.issue_date,'expectedDate',p_row.expected_date,
  'subtotalCents',f.subtotal_cents,'taxCents',f.tax_cents,'totalCents',f.total_cents,'paidCents',f.paid_cents,'balanceCents',f.total_cents-f.paid_cents,
  'lineCount',f.line_count,
  'overdue',p_row.status in('issued','partial') and p_row.expected_date is not null and p_row.expected_date<public.pro_purchase_order_today(),
  'revision',p_row.revision,'issuedAt',p_row.issued_at,'cancelledAt',p_row.cancelled_at,'createdAt',p_row.created_at,'updatedAt',p_row.updated_at)
 from public.pro_purchase_order_figures(p_row.owner_id,p_row.id) f;
$$;

create or replace function public.pro_purchase_order_json(p_row public.pro_purchase_orders) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_purchase_order_summary(p_row)||jsonb_build_object('notes',p_row.notes,'cancelReason',p_row.cancel_reason,
  'lines',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'position',l.position,'description',l.description,'quantity',l.quantity,'unit',l.unit,
    'unitCents',l.unit_cents,'taxRate',l.tax_rate,'subtotalCents',l.subtotal_cents,'taxCents',l.tax_cents,'totalCents',l.subtotal_cents+l.tax_cents,
    'budgetCodeId',l.budget_code_id,'selectionOptionId',l.selection_option_id,'allowanceId',l.allowance_id,
    'receivedQuantity',coalesce((select sum(r.quantity) from public.pro_purchase_order_receipts r where r.owner_id=l.owner_id and r.line_id=l.id),0)) order by l.position)
   from public.pro_purchase_order_lines l where l.owner_id=p_row.owner_id and l.order_id=p_row.id),'[]'::jsonb),
  'receipts',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'lineId',r.line_id,'quantity',r.quantity,'receivedOn',r.received_on,'note',r.note,'createdAt',r.created_at) order by r.created_at,r.id,r.line_id)
   from public.pro_purchase_order_receipts r where r.owner_id=p_row.owner_id and r.order_id=p_row.id),'[]'::jsonb),
  'payments',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'kind',p.kind,'paymentId',p.payment_id,'amountCents',p.amount_cents,'paidOn',p.paid_on,
    'method',p.method,'reference',p.reference,'note',p.note,'createdAt',p.created_at,
    'reversed',p.kind='payment' and exists(select 1 from public.pro_purchase_order_payments x where x.owner_id=p.owner_id and x.payment_id=p.id)) order by p.created_at,p.id)
   from public.pro_purchase_order_payments p where p.owner_id=p_row.owner_id and p.order_id=p_row.id),'[]'::jsonb));
$$;

-- Budget comparison per code: planned (work-budget), committed (lines of non-cancelled
-- orders, tax included), actual (existing work-budget sources) and variance =
-- planned − greatest(committed, actual). Groups roll up their items. Never writes.
create or replace function public.pro_purchase_order_budget(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rows jsonb;totals jsonb;
begin
 with codes as materialized(select * from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=p_work),
 sources as materialized(select * from public.pro_work_budget_sources(p_actor,p_work)),
 committed as materialized(select l.budget_code_id code_id,sum(l.subtotal_cents+l.tax_cents)::bigint cents
   from public.pro_purchase_order_lines l join public.pro_purchase_orders o on o.owner_id=l.owner_id and o.id=l.order_id
   where l.owner_id=p_actor and l.work_id=p_work and o.status<>'cancelled' group by l.budget_code_id),
 items as materialized(select c.id,c.parent_id,c.planned_cents planned,coalesce(m.cents,0)::bigint committed,
   coalesce((select sum(s.amount_cents) from sources s where s.code_id=c.id),0)::bigint actual,
   (select count(*) from sources s where s.code_id=c.id and s.amount_cents is null)::bigint unknown
   from codes c left join committed m on m.code_id=c.id where c.kind='item'),
 grouped as(select c.id,c.kind,c.code,c.title,c.parent_id,c.archived,
   case when c.kind='item' then i.planned else (select sum(x.planned) from items x where x.parent_id=c.id) end planned,
   case when c.kind='item' then i.committed else coalesce((select sum(x.committed) from items x where x.parent_id=c.id),0) end committed,
   case when c.kind='item' then i.actual else coalesce((select sum(x.actual) from items x where x.parent_id=c.id),0) end actual,
   case when c.kind='item' then i.unknown else coalesce((select sum(x.unknown) from items x where x.parent_id=c.id),0) end unknown,
   case when c.kind='item' then greatest(i.committed,i.actual) else coalesce((select sum(greatest(x.committed,x.actual)) from items x where x.parent_id=c.id),0) end projected
   from codes c left join items i on i.id=c.id)
 select coalesce(jsonb_agg(jsonb_build_object('codeId',g.id,'kind',g.kind,'code',g.code,'title',g.title,'parentId',g.parent_id,'archived',g.archived,
   'plannedCents',g.planned,'committedCents',g.committed,'actualCents',g.actual,'unknownCount',g.unknown,'projectedCents',g.projected,
   'varianceCents',case when g.planned is null or g.unknown>0 then null else g.planned-g.projected end)
   order by coalesce((select p.code from codes p where p.id=g.parent_id),g.code),g.parent_id is not null,g.code),'[]'::jsonb) into rows
 from grouped g;
 with sources as materialized(select * from public.pro_work_budget_sources(p_actor,p_work)),
 committed as materialized(select l.budget_code_id code_id,sum(l.subtotal_cents+l.tax_cents)::bigint cents
   from public.pro_purchase_order_lines l join public.pro_purchase_orders o on o.owner_id=l.owner_id and o.id=l.order_id
   where l.owner_id=p_actor and l.work_id=p_work and o.status<>'cancelled' group by l.budget_code_id),
 per_code as(select c.id,c.planned_cents planned,coalesce(m.cents,0)::bigint committed,
   coalesce((select sum(s.amount_cents) from sources s where s.code_id=c.id),0)::bigint actual
   from public.pro_work_budget_codes c left join committed m on m.code_id=c.id where c.owner_id=p_actor and c.work_id=p_work and c.kind='item'),
 loose as(select coalesce((select cents from committed where code_id is null),0)::bigint committed,
   coalesce((select sum(amount_cents) from sources where code_id is null),0)::bigint actual)
 select jsonb_build_object(
   'plannedCents',(select sum(planned)::bigint from per_code),
   'committedCents',coalesce((select sum(cents) from committed),0)::bigint,
   'actualCents',coalesce((select sum(amount_cents) from sources),0)::bigint,
   'unknownCount',(select count(*) from sources where amount_cents is null),
   'uncodedCommittedCents',(select committed from loose),'unassignedActualCents',(select actual from loose),
   'projectedCents',coalesce((select sum(greatest(committed,actual)) from per_code),0)::bigint+(select greatest(committed,actual) from loose),
   'varianceCents',case when (select sum(planned) from per_code) is null or exists(select 1 from sources where amount_cents is null) then null
     else (select sum(planned) from per_code)-coalesce((select sum(greatest(committed,actual)) from per_code),0)-(select greatest(committed,actual) from loose) end)
 into totals;
 return jsonb_build_object('workId',p_work,'currency','CRC','rows',rows,'totals',totals);
end $$;

create or replace function public.pro_purchase_order_references(p_actor uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object(
  'budgetCodes',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'code',c.code,'title',c.title) order by c.code) from public.pro_work_budget_codes c
    where c.owner_id=p_actor and c.work_id=p_work and c.kind='item' and not c.archived
    and (c.parent_id is null or exists(select 1 from public.pro_work_budget_codes p where p.owner_id=c.owner_id and p.work_id=c.work_id and p.id=c.parent_id and not p.archived))),'[]'::jsonb),
  'selectionOptions',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'itemName',i.name,'name',o.name,'brand',o.brand,'quantity',o.quantity,'unitCents',o.unit_cents) order by i.position)
    from public.pro_work_selection_items i join public.pro_work_selection_options o on o.owner_id=i.owner_id and o.id=i.approved_option_id
    where i.owner_id=p_actor and i.work_id=p_work and i.status='approved' and not i.archived),'[]'::jsonb),
  'allowances',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'plannedCents',a.planned_cents) order by a.position)
    from public.pro_work_allowances a where a.owner_id=p_actor and a.work_id=p_work and not a.archived),'[]'::jsonb),
  'suppliers',coalesce((select jsonb_agg(x.item order by x.name,x.id) from (select s.name,s.id,jsonb_build_object('id',s.id,'name',s.name,'email',s.email,'phone',s.phone) item
    from public.pro_expense_suppliers s where s.user_id=p_actor and not s.archived order by s.name,s.id limit 200) x),'[]'::jsonb));
$$;

create or replace function public.pro_purchase_orders_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare wid text;v text;st text;sup text;od boolean;dfrom date;dto date;cur integer;oid uuid;r public.pro_purchase_orders;items jsonb;totals jsonb;more boolean;work_row record;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or jsonb_typeof(p_query->'workId') is distinct from 'string'
  or exists(select 1 from jsonb_object_keys(p_query) k where k not in('workId','view','status','supplier','overdue','from','to','after','id')) then
  raise exception 'Invalid purchase order query' using errcode='22023';end if;
 wid:=p_query->>'workId';v:=coalesce(p_query->>'view','list');
 if length(wid) not between 1 and 160 or v not in('list','detail','budget') then raise exception 'Invalid purchase order query' using errcode='22023';end if;
 select w.id,w.service,w.cancelled into work_row from public.pro_work w where w.user_id=p_actor and w.id=wid;
 if not found then return null;end if;
 if v='budget' then return public.pro_purchase_order_budget(p_actor,wid);end if;
 if v='detail' then
  oid:=(p_query->>'id')::uuid;if oid is null then raise exception 'Order identity required' using errcode='22023';end if;
  select * into r from public.pro_purchase_orders where owner_id=p_actor and work_id=wid and id=oid;
  if not found then return jsonb_build_object('workId',wid,'order',null);end if;
  return jsonb_build_object('workId',wid,'workTitle',work_row.service,'today',public.pro_purchase_order_today(),'order',public.pro_purchase_order_json(r),
   'history',coalesce((select jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_value,'after',h.after_value) order by h.at desc,h.action_id)
    from (select * from public.pro_purchase_order_history h where h.owner_id=p_actor and h.order_id=oid order by h.at desc,h.action_id limit 100) h),'[]'::jsonb));
 end if;
 st:=coalesce(p_query->>'status','all');sup:=nullif(btrim(coalesce(p_query->>'supplier','')),'');od:=coalesce(p_query->>'overdue','0')='1';
 if st not in('all','open','draft','issued','partial','received','cancelled') or length(sup)>160 or coalesce(p_query->>'overdue','0') not in('0','1') then raise exception 'Invalid purchase order filter' using errcode='22023';end if;
 if p_query->>'from' is not null then if not (p_query->>'from')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid date' using errcode='22023';end if;dfrom:=(p_query->>'from')::date;end if;
 if p_query->>'to' is not null then if not (p_query->>'to')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid date' using errcode='22023';end if;dto:=(p_query->>'to')::date;end if;
 if dfrom is not null and dto is not null and dto<dfrom then raise exception 'Invalid date range' using errcode='22023';end if;
 if p_query->>'after' is not null then if not (p_query->>'after')~'^[0-9]{1,6}$' then raise exception 'Invalid cursor' using errcode='22023';end if;cur:=(p_query->>'after')::integer;end if;
 with filtered as materialized(select o.*,public.pro_purchase_order_summary(o) s from public.pro_purchase_orders o
   where o.owner_id=p_actor and o.work_id=wid
    and (st='all' or (st='open' and o.status in('draft','issued','partial')) or o.status=st)
    and (sup is null or lower(o.supplier_name)=lower(sup))
    and (not od or (o.status in('issued','partial') and o.expected_date is not null and o.expected_date<public.pro_purchase_order_today()))
    and (dfrom is null or o.issue_date>=dfrom) and (dto is null or o.issue_date<=dto)),
  page as(select * from filtered where cur is null or number<cur order by number desc limit 21)
 select coalesce((select jsonb_agg(s order by number desc) from (select * from page order by number desc limit 20) p),'[]'::jsonb),
  (select count(*)>20 from page),
  jsonb_build_object('count',(select count(*) from filtered where status<>'cancelled'),
   'totalCents',coalesce((select sum((s->>'totalCents')::bigint) from filtered where status<>'cancelled'),0),
   'paidCents',coalesce((select sum((s->>'paidCents')::bigint) from filtered where status<>'cancelled'),0),
   'balanceCents',coalesce((select sum((s->>'balanceCents')::bigint) from filtered where status<>'cancelled'),0),
   'overdueCount',(select count(*) from filtered where (s->>'overdue')::boolean),
   'cancelledCount',(select count(*) from filtered where status='cancelled'))
 into items,more,totals;
 return jsonb_build_object('workId',wid,'workTitle',work_row.service,'canWrite',not coalesce(work_row.cancelled,false),'today',public.pro_purchase_order_today(),
  'items',items,'nextCursor',case when more then (items->19->>'number')::integer end,'totals',totals,
  'supplierNames',coalesce((select jsonb_agg(n order by lower(n)) from (select distinct on (lower(supplier_name)) supplier_name n from public.pro_purchase_orders where owner_id=p_actor and work_id=wid order by lower(supplier_name),supplier_name) d),'[]'::jsonb),
  'nextNumber',coalesce((select last_number from public.pro_purchase_order_counters where owner_id=p_actor),0)+1,
  'references',public.pro_purchase_order_references(p_actor,wid));
end $$;

-- Optional text: JSON null or a string trimmed to 1..max (empty → null). Raises 22023 otherwise.
create or replace function public.pro_purchase_order_text(p_value jsonb,p_max integer,p_required boolean) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare t text;
begin
 if p_value is null or jsonb_typeof(p_value)='null' then if p_required then raise exception 'Missing text' using errcode='22023';end if;return null;end if;
 if jsonb_typeof(p_value)<>'string' then raise exception 'Invalid text' using errcode='22023';end if;
 t:=btrim(p_value#>>'{}');
 if t='' then if p_required then raise exception 'Missing text' using errcode='22023';end if;return null;end if;
 if length(t)>p_max or t~'[[:cntrl:]]' and p_max<=300 then raise exception 'Invalid text' using errcode='22023';end if;
 return t;
end $$;
create or replace function public.pro_purchase_order_day(p_value jsonb,p_required boolean) returns date
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare d date;
begin
 if p_value is null or jsonb_typeof(p_value)='null' then if p_required then raise exception 'Missing date' using errcode='22023';end if;return null;end if;
 if jsonb_typeof(p_value)<>'string' or not (p_value#>>'{}')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid date' using errcode='22023';end if;
 d:=(p_value#>>'{}')::date;if to_char(d,'YYYY-MM-DD')<>p_value#>>'{}' then raise exception 'Invalid date' using errcode='22023';end if;
 return d;
end $$;

create or replace function public.pro_purchase_orders_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;aid uuid;rid uuid;rev integer;keys text[];expected text[];receipt public.pro_purchase_order_actions;r public.pro_purchase_orders;
 before_json jsonb;after_json jsonb;result jsonb;work_row record;supplier public.pro_expense_suppliers;v_supplier uuid;v_name text;v_contact text;v_title text;v_issue date;v_expected date;v_notes text;
 line jsonb;line_keys text[];n integer;q numeric;tax numeric;unit_cents numeric;v_code uuid;v_option uuid;v_allowance uuid;seen uuid[]:=array[]::uuid[];ordered numeric;received numeric;
 v_day date;v_note text;fig record;amount numeric;v_method text;v_reference text;pay public.pro_purchase_order_payments;next_number integer;all_received boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid purchase order' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'create' then array['action','actionId','expectedDate','id','issueDate','lines','notes','supplierContact','supplierId','supplierName','title','workId']
  when 'update' then array['action','actionId','expectedDate','id','issueDate','lines','notes','revision','supplierContact','supplierId','supplierName','title','workId']
  when 'issue' then array['action','actionId','id','revision','workId']
  when 'cancel' then array['action','actionId','id','reason','revision','workId']
  when 'receive' then array['action','actionId','entries','id','note','receivedOn','revision','workId']
  when 'pay' then array['action','actionId','amountCents','id','method','note','paidOn','reference','revision','workId']
  when 'reverse_payment' then array['action','actionId','id','note','paymentId','revision','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
  or jsonb_typeof(p_input->'id') is distinct from 'string' then raise exception 'Invalid purchase order fields' using errcode='22023';end if;
 if act<>'create' and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'id')::uuid;rev:=case when act<>'create' then (p_input->>'revision')::integer end;
 if length(wid) not between 1 and 160 then raise exception 'Invalid purchase order identity' using errcode='22023';end if;
 -- Shape validation that needs no state (all 22023 → 400).
 if act in('create','update') then
  v_title:=public.pro_purchase_order_text(p_input->'title',160,true);
  v_contact:=public.pro_purchase_order_text(p_input->'supplierContact',200,false);
  v_notes:=public.pro_purchase_order_text(p_input->'notes',2000,false);
  v_issue:=public.pro_purchase_order_day(p_input->'issueDate',true);v_expected:=public.pro_purchase_order_day(p_input->'expectedDate',false);
  if v_expected is not null and v_expected<v_issue then raise exception 'Expected date before issue date' using errcode='22023';end if;
  if jsonb_typeof(p_input->'supplierId') not in('string','null') then raise exception 'Invalid supplier' using errcode='22023';end if;
  v_supplier:=(p_input->>'supplierId')::uuid;
  if v_supplier is null then v_name:=public.pro_purchase_order_text(p_input->'supplierName',160,true);
  elsif jsonb_typeof(p_input->'supplierName') is distinct from 'null' then raise exception 'Supplier name comes from the supplier' using errcode='22023';end if;
  if jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_array_length(p_input->'lines') not between 1 and 100 then raise exception 'Invalid lines' using errcode='22023';end if;
  for line in select value from jsonb_array_elements(p_input->'lines') loop
   select array_agg(key order by key) into line_keys from jsonb_object_keys(line) key;
   if jsonb_typeof(line) is distinct from 'object' or line_keys is distinct from array['allowanceId','budgetCodeId','description','id','quantity','selectionOptionId','taxRate','unit','unitCents']
    or jsonb_typeof(line->'id') is distinct from 'string' or jsonb_typeof(line->'quantity') is distinct from 'number' or jsonb_typeof(line->'unitCents') is distinct from 'number'
    or jsonb_typeof(line->'taxRate') is distinct from 'number' or jsonb_typeof(line->'budgetCodeId') not in('string','null')
    or jsonb_typeof(line->'selectionOptionId') not in('string','null') or jsonb_typeof(line->'allowanceId') not in('string','null') then raise exception 'Invalid line fields' using errcode='22023';end if;
   perform public.pro_purchase_order_text(line->'description',300,true);perform public.pro_purchase_order_text(line->'unit',20,true);
   q:=(line->>'quantity')::numeric;tax:=(line->>'taxRate')::numeric;unit_cents:=(line->>'unitCents')::numeric;
   if q<>round(q,3) or q not between 0.001 and 1000000 or tax<>round(tax,2) or tax not between 0 and 100 or unit_cents<>round(unit_cents) or unit_cents not between 0 and 10000000000
    or round(q*unit_cents)>10000000000 then raise exception 'Invalid line values' using errcode='22023';end if;
   if line->>'selectionOptionId' is not null and line->>'allowanceId' is not null then raise exception 'Link a selection or an allowance, not both' using errcode='22023';end if;
   if (line->>'id')::uuid=any(seen) then raise exception 'Duplicated line' using errcode='22023';end if;seen:=seen||(line->>'id')::uuid;
  end loop;
 elsif act='cancel' then v_note:=public.pro_purchase_order_text(p_input->'reason',300,false);
 elsif act='receive' then
  v_day:=public.pro_purchase_order_day(p_input->'receivedOn',true);v_note:=public.pro_purchase_order_text(p_input->'note',300,false);
  if jsonb_typeof(p_input->'entries') is distinct from 'array' or jsonb_array_length(p_input->'entries') not between 1 and 100 then raise exception 'Invalid receipt' using errcode='22023';end if;
  for line in select value from jsonb_array_elements(p_input->'entries') loop
   select array_agg(key order by key) into line_keys from jsonb_object_keys(line) key;
   if jsonb_typeof(line) is distinct from 'object' or line_keys is distinct from array['lineId','quantity'] or jsonb_typeof(line->'lineId') is distinct from 'string' or jsonb_typeof(line->'quantity') is distinct from 'number' then raise exception 'Invalid receipt entry' using errcode='22023';end if;
   q:=(line->>'quantity')::numeric;if q<>round(q,3) or q not between 0.001 and 1000000 then raise exception 'Invalid receipt quantity' using errcode='22023';end if;
   if (line->>'lineId')::uuid=any(seen) then raise exception 'Duplicated receipt line' using errcode='22023';end if;seen:=seen||(line->>'lineId')::uuid;
  end loop;
 elsif act='pay' then
  if jsonb_typeof(p_input->'amountCents') is distinct from 'number' or jsonb_typeof(p_input->'method') is distinct from 'string' then raise exception 'Invalid payment' using errcode='22023';end if;
  amount:=(p_input->>'amountCents')::numeric;v_method:=p_input->>'method';v_day:=public.pro_purchase_order_day(p_input->'paidOn',true);
  v_reference:=public.pro_purchase_order_text(p_input->'reference',160,false);v_note:=public.pro_purchase_order_text(p_input->'note',300,false);
  if amount<>round(amount) or amount not between 1 and 10000000000000 or v_method not in('transfer','sinpe','cash','card','check','other') then raise exception 'Invalid payment values' using errcode='22023';end if;
 elsif act='reverse_payment' then
  if jsonb_typeof(p_input->'paymentId') is distinct from 'string' then raise exception 'Invalid reversal' using errcode='22023';end if;
  v_note:=public.pro_purchase_order_text(p_input->'note',300,true);
 end if;
 select w.id,w.cancelled into work_row from public.pro_work w where w.user_id=p_actor and w.id=wid;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-purchase-order-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_purchase_order_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-purchase-order-work:'||p_actor::text||':'||wid,0));
 if coalesce(work_row.cancelled,false) and act in('create','update','issue') then raise exception 'Restore the job before ordering' using errcode='40001';end if;
 if act in('create','update') then
  if v_supplier is not null then
   select * into supplier from public.pro_expense_suppliers where user_id=p_actor and id=v_supplier;
   if not found then raise exception 'Unknown supplier' using errcode='22023';end if;
   v_name:=supplier.name;
  end if;
 end if;
 if act='create' then
  if exists(select 1 from public.pro_purchase_orders where id=rid) then raise exception 'Order id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_purchase_orders where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Purchase order limit' using errcode='54000';end if;
  if supplier.id is not null and supplier.archived then raise exception 'Archived supplier' using errcode='22023';end if;
  -- Per-account number: row lock serializes creators; a failed transaction rolls the counter back (no gaps).
  insert into public.pro_purchase_order_counters(owner_id) values(p_actor) on conflict(owner_id) do nothing;
  update public.pro_purchase_order_counters set last_number=last_number+1 where owner_id=p_actor returning last_number into next_number;
  insert into public.pro_purchase_orders(owner_id,id,work_id,number,supplier_id,supplier_name,supplier_contact,title,issue_date,expected_date,notes)
   values(p_actor,rid,wid,next_number,v_supplier,v_name,v_contact,v_title,v_issue,v_expected,v_notes) returning * into r;
  before_json:=null;
 else
  select * into r from public.pro_purchase_orders where owner_id=p_actor and id=rid and work_id=wid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if r.revision<>rev then raise exception 'Purchase order changed' using errcode='40001';end if;
  before_json:=public.pro_purchase_order_json(r);
  select * into fig from public.pro_purchase_order_figures(p_actor,rid);
  if act='update' then
   if r.status not in('draft','issued') or exists(select 1 from public.pro_purchase_order_receipts where owner_id=p_actor and order_id=rid) then raise exception 'Only orders without receipts can be edited' using errcode='22023';end if;
   if supplier.id is not null and supplier.archived and r.supplier_id is distinct from supplier.id then raise exception 'Archived supplier' using errcode='22023';end if;
   if r.supplier_id=v_supplier then v_name:=r.supplier_name;end if;
   if exists(select 1 from public.pro_purchase_order_payments where owner_id=p_actor and order_id=rid and paid_on<v_issue) then raise exception 'Payments before issue date' using errcode='22023';end if;
   update public.pro_purchase_orders set supplier_id=v_supplier,supplier_name=v_name,supplier_contact=v_contact,title=v_title,issue_date=v_issue,expected_date=v_expected,notes=v_notes,revision=revision+1,updated_at=now()
    where owner_id=p_actor and id=rid returning * into r;
   delete from public.pro_purchase_order_lines where owner_id=p_actor and order_id=rid;
  elsif act='issue' then
   if r.status<>'draft' then raise exception 'Only drafts can be issued' using errcode='22023';end if;
   update public.pro_purchase_orders set status='issued',issued_at=now(),revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='cancel' then
   if r.status not in('draft','issued','partial') then raise exception 'Order cannot be cancelled' using errcode='22023';end if;
   if fig.paid_cents<>0 then raise exception 'Reverse payments before cancelling' using errcode='22023';end if;
   update public.pro_purchase_orders set status='cancelled',cancelled_at=now(),cancel_reason=v_note,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='receive' then
   if r.status not in('issued','partial') then raise exception 'Issue the order before receiving' using errcode='22023';end if;
   if v_day<r.issue_date or v_day>public.pro_purchase_order_today() then raise exception 'Invalid receipt date' using errcode='22023';end if;
   for line in select value from jsonb_array_elements(p_input->'entries') loop
    select l.quantity into ordered from public.pro_purchase_order_lines l where l.owner_id=p_actor and l.order_id=rid and l.id=(line->>'lineId')::uuid;
    if not found then raise exception 'Unknown line' using errcode='22023';end if;
    select coalesce(sum(x.quantity),0) into received from public.pro_purchase_order_receipts x where x.owner_id=p_actor and x.line_id=(line->>'lineId')::uuid;
    if received+(line->>'quantity')::numeric>ordered then raise exception 'Received more than ordered' using errcode='22023';end if;
    insert into public.pro_purchase_order_receipts(owner_id,order_id,id,line_id,quantity,received_on,note) values(p_actor,rid,aid,(line->>'lineId')::uuid,(line->>'quantity')::numeric,v_day,v_note);
   end loop;
   select bool_and(coalesce((select sum(x.quantity) from public.pro_purchase_order_receipts x where x.owner_id=l.owner_id and x.line_id=l.id),0)>=l.quantity) into all_received
    from public.pro_purchase_order_lines l where l.owner_id=p_actor and l.order_id=rid;
   update public.pro_purchase_orders set status=case when all_received then 'received' else 'partial' end,revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='pay' then
   if r.status not in('issued','partial','received') then raise exception 'Issue the order before paying' using errcode='22023';end if;
   if v_day<r.issue_date or v_day>public.pro_purchase_order_today() then raise exception 'Invalid payment date' using errcode='22023';end if;
   if amount>fig.total_cents-fig.paid_cents then raise exception 'Payment exceeds balance' using errcode='22023';end if;
   insert into public.pro_purchase_order_payments(owner_id,order_id,id,kind,amount_cents,paid_on,method,reference,note) values(p_actor,rid,aid,'payment',amount::bigint,v_day,v_method,v_reference,v_note);
   update public.pro_purchase_orders set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  elsif act='reverse_payment' then
   select * into pay from public.pro_purchase_order_payments where owner_id=p_actor and order_id=rid and id=(p_input->>'paymentId')::uuid and kind='payment';
   if not found or exists(select 1 from public.pro_purchase_order_payments where owner_id=p_actor and payment_id=pay.id) then raise exception 'Invalid reversal' using errcode='22023';end if;
   insert into public.pro_purchase_order_payments(owner_id,order_id,id,kind,payment_id,amount_cents,paid_on,method,reference,note)
    values(p_actor,rid,aid,'reverse',pay.id,pay.amount_cents,greatest(pay.paid_on,public.pro_purchase_order_today()),pay.method,pay.reference,v_note);
   update public.pro_purchase_orders set revision=revision+1,updated_at=now() where owner_id=p_actor and id=rid returning * into r;
  end if;
 end if;
 if act in('create','update') then
  n:=0;
  for line in select value from jsonb_array_elements(p_input->'lines') loop
   n:=n+1;v_code:=(line->>'budgetCodeId')::uuid;v_option:=(line->>'selectionOptionId')::uuid;v_allowance:=(line->>'allowanceId')::uuid;
   if v_code is not null and not exists(select 1 from public.pro_work_budget_codes c where c.owner_id=p_actor and c.work_id=wid and c.id=v_code and c.kind='item' and not c.archived) then
    raise exception 'Choose an active budget item' using errcode='22023';end if;
   if v_option is not null and not exists(select 1 from public.pro_work_selection_items i where i.owner_id=p_actor and i.work_id=wid and i.approved_option_id=v_option and i.status='approved' and not i.archived) then
    raise exception 'Choose an approved selection option' using errcode='22023';end if;
   if v_allowance is not null and not exists(select 1 from public.pro_work_allowances a where a.owner_id=p_actor and a.work_id=wid and a.id=v_allowance and not a.archived) then
    raise exception 'Choose an active allowance' using errcode='22023';end if;
   if exists(select 1 from public.pro_purchase_order_lines where id=(line->>'id')::uuid and not(owner_id=p_actor and order_id=rid)) then raise exception 'Line id already used' using errcode='23505';end if;
   insert into public.pro_purchase_order_lines(owner_id,work_id,order_id,id,position,description,quantity,unit,unit_cents,tax_rate,budget_code_id,selection_option_id,allowance_id)
    values(p_actor,wid,rid,(line->>'id')::uuid,n,btrim(line->>'description'),(line->>'quantity')::numeric,btrim(line->>'unit'),(line->>'unitCents')::bigint,(line->>'taxRate')::numeric,v_code,v_option,v_allowance);
  end loop;
  select * into fig from public.pro_purchase_order_figures(p_actor,rid);
  if fig.paid_cents>fig.total_cents then raise exception 'Total below payments' using errcode='22023';end if;
  if before_json is not null and before_json-'revision'-'updatedAt'-'receipts'-'payments'-'paidCents'-'balanceCents'-'overdue'
   =public.pro_purchase_order_json(r)-'revision'-'updatedAt'-'receipts'-'payments'-'paidCents'-'balanceCents'-'overdue' then
   raise exception 'No purchase order changes' using errcode='22023';end if;
 end if;
 after_json:=public.pro_purchase_order_json(r);result:=jsonb_build_object('order',after_json);
 insert into public.pro_purchase_order_history(owner_id,work_id,order_id,action_id,action,before_value,after_value) values(p_actor,wid,rid,aid,act,before_json,after_json);
 insert into public.pro_purchase_order_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

create or replace function public.pro_purchase_order_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Purchase order history, receipts and payments are immutable' using errcode='23514';
end $$;
drop trigger if exists pro_purchase_order_history_immutable on public.pro_purchase_order_history;
create trigger pro_purchase_order_history_immutable before update on public.pro_purchase_order_history for each row execute function public.pro_purchase_order_immutable();
drop trigger if exists pro_purchase_order_action_immutable on public.pro_purchase_order_actions;
create trigger pro_purchase_order_action_immutable before update on public.pro_purchase_order_actions for each row execute function public.pro_purchase_order_immutable();
drop trigger if exists pro_purchase_order_receipt_immutable on public.pro_purchase_order_receipts;
create trigger pro_purchase_order_receipt_immutable before update on public.pro_purchase_order_receipts for each row execute function public.pro_purchase_order_immutable();
drop trigger if exists pro_purchase_order_payment_immutable on public.pro_purchase_order_payments;
create trigger pro_purchase_order_payment_immutable before update on public.pro_purchase_order_payments for each row execute function public.pro_purchase_order_immutable();

do $$declare t text;f record;begin
 foreach t in array array['pro_purchase_order_counters','pro_purchase_orders','pro_purchase_order_lines','pro_purchase_order_receipts','pro_purchase_order_payments','pro_purchase_order_history','pro_purchase_order_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname like 'pro_purchase_order%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname<>'pro_purchase_order_immutable' then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== project-schedule-local.sql =====
-- LOCAL PRO ONLY. Project schedule (families 13/79): full Gantt read over the existing
-- plan (phases, planned periods, informative predecessors, key dates), immutable
-- baselines with per-task/phase/milestone deviation, and an opt-in customer view
-- (pro_client_dashboards.show_schedule, off by default) without internal data.
-- Does not alter tasks, plans, dependencies, milestones, receipts or their writers.
begin;
create table if not exists public.pro_work_schedule_baselines(
 owner_id uuid not null,work_id text not null,id uuid not null,
 title text not null check(length(btrim(title)) between 1 and 120),
 schedule_revision integer not null check(schedule_revision>=0),
 task_count integer not null check(task_count between 0 and 500),milestone_count integer not null check(milestone_count between 0 and 500),
 seq bigint generated always as identity,captured_at timestamptz not null default now(),
 primary key(owner_id,work_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_schedule_baselines_latest on public.pro_work_schedule_baselines(owner_id,work_id,seq desc);
create table if not exists public.pro_work_schedule_baseline_items(
 owner_id uuid not null,work_id text not null,baseline_id uuid not null,
 kind text not null check(kind in('task','milestone')),ref_id uuid not null,phase_id uuid,
 title text not null check(length(title) between 1 and 160),planned_start date not null,planned_end date not null,
 check(planned_start<=planned_end),check(kind='task' or(planned_start=planned_end and phase_id is null)),
 primary key(owner_id,work_id,baseline_id,kind,ref_id),
 foreign key(owner_id,work_id,baseline_id) references public.pro_work_schedule_baselines(owner_id,work_id,id) on delete cascade
);
create table if not exists public.pro_work_schedule_baseline_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,work_id text not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(actor_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
-- Baselines are snapshots: no row is ever updated, and only a cascade from the
-- job/account (trigger depth >= 2) may delete them.
create or replace function public.pro_work_schedule_baseline_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' and pg_trigger_depth()>=2 then return old;end if;
 raise exception 'Schedule baselines are immutable' using errcode='23514';
end $$;
drop trigger if exists pro_work_schedule_baselines_immutable on public.pro_work_schedule_baselines;
create trigger pro_work_schedule_baselines_immutable before update or delete on public.pro_work_schedule_baselines for each row execute function public.pro_work_schedule_baseline_immutable();
drop trigger if exists pro_work_schedule_baseline_items_immutable on public.pro_work_schedule_baseline_items;
create trigger pro_work_schedule_baseline_items_immutable before update or delete on public.pro_work_schedule_baseline_items for each row execute function public.pro_work_schedule_baseline_immutable();
drop trigger if exists pro_work_schedule_baseline_actions_immutable on public.pro_work_schedule_baseline_actions;
create trigger pro_work_schedule_baseline_actions_immutable before update or delete on public.pro_work_schedule_baseline_actions for each row execute function public.pro_work_schedule_baseline_immutable();

create or replace function public.pro_work_schedule_baseline_json(p_row public.pro_work_schedule_baselines) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'title',p_row.title,'capturedAt',p_row.captured_at,'scheduleRevision',p_row.schedule_revision,'taskCount',p_row.task_count,'milestoneCount',p_row.milestone_count);
$$;

-- Owner Gantt: every active task (plan limit 500), all active phases and key dates,
-- the latest baseline and deviation in civil days (positive = later than baseline).
create or replace function public.pro_work_gantt_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rev integer;base public.pro_work_schedule_baselines;tasks jsonb;phases jsonb;milestones jsonb;baselines jsonb;today date;show boolean;cur_end date;base_end date;cur_start date;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid schedule query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 today:=(now() at time zone 'America/Costa_Rica')::date;
 select revision into rev from public.pro_work_schedule_heads where owner_id=p_actor and work_id=p_work;
 select * into base from public.pro_work_schedule_baselines where owner_id=p_actor and work_id=p_work order by seq desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',t.id,'title',t.title,'status',t.status,'revision',t.revision,
   'dueDate',case when t.due_date is null then null else to_char(t.due_date,'YYYY-MM-DD') end,
   'phaseId',p.phase_id,'plannedStart',to_char(p.planned_start,'YYYY-MM-DD'),'plannedEnd',to_char(p.planned_end,'YYYY-MM-DD'),
   'dependsOn',coalesce((select jsonb_agg(d.predecessor_id order by d.predecessor_id) from public.pro_work_schedule_dependencies d where d.owner_id=t.owner_id and d.work_id=t.work_id and d.task_id=t.id),'[]'::jsonb),
   'baselineStart',to_char(b.planned_start,'YYYY-MM-DD'),'baselineEnd',to_char(b.planned_end,'YYYY-MM-DD'),
   'startVarianceDays',case when p.planned_start is null or b.planned_start is null then null else p.planned_start-b.planned_start end,
   'endVarianceDays',case when p.planned_end is null or b.planned_end is null then null else p.planned_end-b.planned_end end
  ) order by p.planned_start nulls last,t.title,t.id),'[]'::jsonb) into tasks
 from (select * from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and not archived order by id limit 500) t
 left join public.pro_work_schedule_plans p on p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id
 left join public.pro_work_schedule_baseline_items b on base.id is not null and b.owner_id=t.owner_id and b.work_id=t.work_id and b.baseline_id=base.id and b.kind='task' and b.ref_id=t.id;
 select coalesce(jsonb_agg(x.content order by x.position,x.id),'[]'::jsonb) into phases from (
  select ph.position,ph.id,jsonb_build_object('id',ph.id,'title',ph.title,'position',ph.position,
   'plannedStart',to_char(min(p.planned_start),'YYYY-MM-DD'),'plannedEnd',to_char(max(p.planned_end),'YYYY-MM-DD'),
   'taskCount',count(t.id),'doneCount',count(t.id) filter(where t.status='done'),
   'baselineStart',to_char((select min(b.planned_start) from public.pro_work_schedule_baseline_items b where base.id is not null and b.owner_id=p_actor and b.work_id=p_work and b.baseline_id=base.id and b.kind='task' and b.phase_id=ph.id),'YYYY-MM-DD'),
   'baselineEnd',to_char((select max(b.planned_end) from public.pro_work_schedule_baseline_items b where base.id is not null and b.owner_id=p_actor and b.work_id=p_work and b.baseline_id=base.id and b.kind='task' and b.phase_id=ph.id),'YYYY-MM-DD'),
   'endVarianceDays',max(p.planned_end)-(select max(b.planned_end) from public.pro_work_schedule_baseline_items b where base.id is not null and b.owner_id=p_actor and b.work_id=p_work and b.baseline_id=base.id and b.kind='task' and b.phase_id=ph.id)
  ) content
  from public.pro_work_schedule_phases ph
  left join public.pro_work_schedule_plans p on p.owner_id=ph.owner_id and p.work_id=ph.work_id and p.phase_id=ph.id
   and exists(select 1 from public.pro_work_tasks a where a.owner_id=p.owner_id and a.work_id=p.work_id and a.id=p.task_id and not a.archived)
  left join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
  where ph.owner_id=p_actor and ph.work_id=p_work and not ph.archived
  group by ph.id,ph.position,ph.title limit 50
 ) x;
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'date',to_char(m.milestone_date,'YYYY-MM-DD'),'notes',m.notes,
   'baselineDate',to_char(b.planned_start,'YYYY-MM-DD'),'varianceDays',case when b.planned_start is null then null else m.milestone_date-b.planned_start end) order by m.milestone_date,m.id),'[]'::jsonb) into milestones
 from (select * from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=p_work and not archived order by milestone_date,id limit 500) m
 left join public.pro_work_schedule_baseline_items b on base.id is not null and b.owner_id=m.owner_id and b.work_id=m.work_id and b.baseline_id=base.id and b.kind='milestone' and b.ref_id=m.id;
 select coalesce(jsonb_agg(public.pro_work_schedule_baseline_json(x) order by x.seq desc),'[]'::jsonb) into baselines from (select * from public.pro_work_schedule_baselines where owner_id=p_actor and work_id=p_work order by seq desc limit 20) x;
 select coalesce(show_schedule,false) into show from public.pro_client_dashboards where owner_id=p_actor and work_id=p_work;
 select max(p.planned_end),min(p.planned_start) into cur_end,cur_start from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived where p.owner_id=p_actor and p.work_id=p_work;
 if base.id is not null then select max(planned_end) into base_end from public.pro_work_schedule_baseline_items where owner_id=p_actor and work_id=p_work and baseline_id=base.id and kind='task';end if;
 return jsonb_build_object('workId',p_work,'revision',coalesce(rev,0),'today',to_char(today,'YYYY-MM-DD'),
  'plannedStart',to_char(cur_start,'YYYY-MM-DD'),'plannedEnd',to_char(cur_end,'YYYY-MM-DD'),
  'baseline',case when base.id is null then null else public.pro_work_schedule_baseline_json(base) end,
  'baselineEnd',to_char(base_end,'YYYY-MM-DD'),'endVarianceDays',case when cur_end is null or base_end is null then null else cur_end-base_end end,
  'baselines',baselines,'phases',phases,'tasks',tasks,'milestones',milestones,'showSchedule',coalesce(show,false));
end $$;

create or replace function public.pro_work_schedule_baseline_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];wid text;aid uuid;rev integer;current_rev integer;title_text text;receipt public.pro_work_schedule_baseline_actions;bid uuid;tc integer;mc integer;row public.pro_work_schedule_baselines;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid baseline' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if p_input->>'action' is distinct from 'baseline_save' or keys is distinct from array['action','actionId','revision','title','workId']
  or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'title') is distinct from 'string'
  or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric>2147483646
 then raise exception 'Invalid baseline fields' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;title_text:=btrim(p_input->>'title');
 if length(wid) not between 1 and 160 or length(title_text) not between 1 and 120 then raise exception 'Invalid baseline content' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-baseline-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_schedule_baseline_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 -- Same serialization as every plan writer, so the snapshot matches one revision.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 select revision into current_rev from public.pro_work_schedule_heads where owner_id=p_actor and work_id=wid;current_rev:=coalesce(current_rev,0);
 if rev<>current_rev then raise exception 'Schedule changed' using errcode='40001';end if;
 if (select count(*) from public.pro_work_schedule_baselines where owner_id=p_actor and work_id=wid)>=20 then raise exception 'Baseline limit reached' using errcode='54000';end if;
 select count(*) into tc from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived where p.owner_id=p_actor and p.work_id=wid and p.planned_start is not null;
 select count(*) into mc from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=wid and not archived;
 if tc=0 and mc=0 then raise exception 'Nothing to capture' using errcode='22023';end if;
 if tc>500 or mc>500 then raise exception 'Baseline too large' using errcode='54000';end if;
 bid:=gen_random_uuid();
 insert into public.pro_work_schedule_baselines(owner_id,work_id,id,title,schedule_revision,task_count,milestone_count) values(p_actor,wid,bid,title_text,current_rev,tc,mc) returning * into row;
 insert into public.pro_work_schedule_baseline_items(owner_id,work_id,baseline_id,kind,ref_id,phase_id,title,planned_start,planned_end)
  select p_actor,wid,bid,'task',t.id,p.phase_id,t.title,p.planned_start,p.planned_end from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived where p.owner_id=p_actor and p.work_id=wid and p.planned_start is not null
  union all select p_actor,wid,bid,'milestone',m.id,null,m.title,m.milestone_date,m.milestone_date from public.pro_work_schedule_milestones m where m.owner_id=p_actor and m.work_id=wid and not m.archived;
 result:=jsonb_build_object('baseline',public.pro_work_schedule_baseline_json(row));
 insert into public.pro_work_schedule_baseline_actions(actor_id,action_id,work_id,input,result) values(p_actor,aid,wid,p_input,result);
 return result;
end $$;

-- Customer view: phases (title, overall period, progress counts), tasks without a
-- phase grouped as one row, and key dates. Never task titles, notes, assignees,
-- dependencies, baselines or revisions. Same audience/gating as allowances.
create or replace function public.pro_work_schedule_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;req_status text;enabled boolean;phases jsonb;general jsonb;milestones jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select coalesce(show_schedule,false) into enabled from public.pro_client_dashboards where owner_id=owner and work_id=wid;
 if req_status not in('confirmed','completed') or not coalesce(enabled,false) then return jsonb_build_object('visible',false);end if;
 select coalesce(jsonb_agg(x.content order by x.position,x.start nulls last),'[]'::jsonb) into phases from (
  select ph.position,min(p.planned_start) start,jsonb_build_object('title',ph.title,'plannedStart',to_char(min(p.planned_start),'YYYY-MM-DD'),'plannedEnd',to_char(max(p.planned_end),'YYYY-MM-DD'),
   'total',count(t.id),'done',count(t.id) filter(where t.status='done')) content
  from public.pro_work_schedule_phases ph
  left join public.pro_work_schedule_plans p on p.owner_id=ph.owner_id and p.work_id=ph.work_id and p.phase_id=ph.id
   and exists(select 1 from public.pro_work_tasks a where a.owner_id=p.owner_id and a.work_id=p.work_id and a.id=p.task_id and not a.archived)
  left join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
  where ph.owner_id=owner and ph.work_id=wid and not ph.archived group by ph.id,ph.position,ph.title limit 50
 ) x;
 select case when count(t.id)=0 then null else jsonb_build_object('plannedStart',to_char(min(p.planned_start),'YYYY-MM-DD'),'plannedEnd',to_char(max(p.planned_end),'YYYY-MM-DD'),'total',count(t.id),'done',count(t.id) filter(where t.status='done')) end into general
  from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived
  where p.owner_id=owner and p.work_id=wid and p.planned_start is not null and(p.phase_id is null or not exists(select 1 from public.pro_work_schedule_phases ph where ph.owner_id=p.owner_id and ph.work_id=p.work_id and ph.id=p.phase_id and not ph.archived));
 select coalesce(jsonb_agg(jsonb_build_object('title',m.title,'date',to_char(m.milestone_date,'YYYY-MM-DD')) order by m.milestone_date,m.id),'[]'::jsonb) into milestones
  from (select * from public.pro_work_schedule_milestones where owner_id=owner and work_id=wid and not archived order by milestone_date,id limit 200) m;
 return jsonb_build_object('visible',true,'today',to_char((now() at time zone 'America/Costa_Rica')::date,'YYYY-MM-DD'),'phases',phases,'general',general,'milestones',milestones);
end $$;

alter table public.pro_work_schedule_baselines enable row level security;
alter table public.pro_work_schedule_baseline_items enable row level security;
alter table public.pro_work_schedule_baseline_actions enable row level security;
revoke all on public.pro_work_schedule_baselines,public.pro_work_schedule_baseline_items,public.pro_work_schedule_baseline_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_schedule_baselines,public.pro_work_schedule_baseline_items,public.pro_work_schedule_baseline_actions to service_role;
grant usage,select on sequence public.pro_work_schedule_baselines_seq_seq to service_role;
revoke all on function public.pro_work_schedule_baseline_immutable(),public.pro_work_schedule_baseline_json(public.pro_work_schedule_baselines),public.pro_work_gantt_read(uuid,text),public.pro_work_schedule_baseline_mutate(uuid,jsonb),public.pro_work_schedule_client_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_work_schedule_baseline_json(public.pro_work_schedule_baselines),public.pro_work_gantt_read(uuid,text),public.pro_work_schedule_baseline_mutate(uuid,jsonb),public.pro_work_schedule_client_read(uuid,uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== work-punchlist-local.sql =====
-- LOCAL PRO ONLY. Punch list (family 15): closing items are ordinary job tasks
-- (pro_work_tasks) carrying a 1:1 punch marker with an optional job photo
-- (pro_work_files, JPEG) and an optional "photo required to complete" rule.
-- Every task change goes through the existing pro_work_tasks_mutate writer, so
-- task history, receipts and CAS stay the single source of truth. The customer
-- sees the list only when pro_client_dashboards.show_punchlist is on (off by
-- default): title, status, due date and photo; never notes, assignee or history.
begin;
create table if not exists public.pro_work_punch_items(
 owner_id uuid not null,work_id text not null,task_id uuid not null,photo_file_id uuid,photo_required boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,work_id,task_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,work_id,photo_file_id) references public.pro_work_files(owner_id,work_id,id) on delete set null (photo_file_id)
);
create table if not exists public.pro_work_punch_history(
 owner_id uuid not null,work_id text not null,task_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','complete','reopen','archive','mark')),
 before_item jsonb,after_item jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_punch_items(owner_id,work_id,task_id) on delete cascade
);
create table if not exists public.pro_work_punch_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create or replace function public.pro_work_punch_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Punch list history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_punch_history_immutable on public.pro_work_punch_history;
create trigger pro_work_punch_history_immutable before update on public.pro_work_punch_history for each row execute function public.pro_work_punch_immutable();
drop trigger if exists pro_work_punch_actions_immutable on public.pro_work_punch_actions;
create trigger pro_work_punch_actions_immutable before update on public.pro_work_punch_actions for each row execute function public.pro_work_punch_immutable();

-- QA 2026-11-11: punch items are ordinary tasks, so they can also be completed from
-- the task list, the task center or a team member. The "photo required" rule is
-- enforced on the task row itself, for every writer, not only in this module.
create or replace function public.pro_work_punch_photo_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if exists(select 1 from public.pro_work_punch_items p where p.owner_id=new.owner_id and p.work_id=new.work_id and p.task_id=new.id and p.photo_required
   and not exists(select 1 from public.pro_work_files f where f.owner_id=p.owner_id and f.work_id=p.work_id and f.id=p.photo_file_id and f.ready and f.mime_type='image/jpeg'))
 then raise exception 'Photo required before completing' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_work_punch_photo_guard on public.pro_work_tasks;
create trigger pro_work_punch_photo_guard before update of status on public.pro_work_tasks for each row when(new.status='done' and old.status is distinct from 'done') execute function public.pro_work_punch_photo_guard();

create or replace function public.pro_work_punch_json(p_owner uuid,p_work text,p_task uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('taskId',t.id,'workId',t.work_id,'title',t.title,'details',t.details,'assignee',t.assignee,
  'dueDate',case when t.due_date is null then null else to_char(t.due_date,'YYYY-MM-DD') end,'status',t.status,'archived',t.archived,'taskRevision',t.revision,
  'revision',p.revision,'photoRequired',p.photo_required,'photoFileId',f.id,'photoName',f.name,'createdAt',p.created_at,'updatedAt',greatest(p.updated_at,t.updated_at))
 from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
 left join public.pro_work_files f on f.owner_id=p.owner_id and f.work_id=p.work_id and f.id=p.photo_file_id and f.ready and f.mime_type='image/jpeg'
 where p.owner_id=p_owner and p.work_id=p_work and p.task_id=p_task;
$$;

create or replace function public.pro_work_punchlist_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;candidates jsonb;total integer;done integer;show boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid punch list query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select coalesce(jsonb_agg(public.pro_work_punch_json(p_actor,p_work,x.task_id) order by x.due_date nulls last,x.created_at,x.task_id),'[]'::jsonb),count(*),count(*) filter(where x.status='done') into items,total,done
  from (select p.task_id,p.created_at,t.due_date,t.status from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
   where p.owner_id=p_actor and p.work_id=p_work and not t.archived order by t.due_date nulls last,p.created_at,p.task_id limit 500) x;
 -- Open tasks that can be moved to the punch list (first 50 by title).
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title) order by t.title,t.id),'[]'::jsonb) into candidates from (
  select t.id,t.title from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=p_work and not t.archived and t.status='open'
   and not exists(select 1 from public.pro_work_punch_items p where p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id) order by t.title,t.id limit 50) t;
 select coalesce(show_punchlist,false) into show from public.pro_client_dashboards where owner_id=p_actor and work_id=p_work;
 return jsonb_build_object('workId',p_work,'items',items,'counts',jsonb_build_object('total',coalesce(total,0),'done',coalesce(done,0)),'candidates',candidates,'showPunchlist',coalesce(show,false));
end $$;

create or replace function public.pro_work_punchlist_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;wid text;tid uuid;aid uuid;task_action uuid;keys text[];expected text[];receipt public.pro_work_punch_actions;item public.pro_work_punch_items;task public.pro_work_tasks;
 photo uuid;required boolean;before_json jsonb;after_json jsonb;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid punch item' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'create' then array['action','actionId','assignee','details','dueDate','photoFileId','photoRequired','taskId','title','workId']
  when 'update' then array['action','actionId','assignee','details','dueDate','photoFileId','photoRequired','revision','taskId','taskRevision','title','workId']
  when 'complete' then array['action','actionId','taskId','taskRevision','workId'] when 'reopen' then array['action','actionId','taskId','taskRevision','workId']
  when 'archive' then array['action','actionId','taskId','taskRevision','workId'] when 'mark' then array['action','actionId','taskId','workId'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string'
 then raise exception 'Invalid punch item fields' using errcode='22023';end if;
 if act in('update','complete','reopen','archive') and (jsonb_typeof(p_input->'taskRevision') is distinct from 'number' or not coalesce((p_input->>'taskRevision')~'^[0-9]{1,10}$',false) or (p_input->>'taskRevision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 if act='update' and (jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 if act in('create','update') then
  if jsonb_typeof(p_input->'photoFileId') not in('string','null') or jsonb_typeof(p_input->'photoRequired') is distinct from 'boolean' then raise exception 'Invalid punch photo' using errcode='22023';end if;
  photo:=(p_input->>'photoFileId')::uuid;required:=(p_input->>'photoRequired')::boolean;
 end if;
 wid:=p_input->>'workId';tid:=(p_input->>'taskId')::uuid;aid:=(p_input->>'actionId')::uuid;
 if length(wid) not between 1 and 160 then raise exception 'Invalid punch scope' using errcode='22023';end if;
 -- Deterministic identity for the inner task write: a retry replays both receipts.
 task_action:=overlay(overlay(md5('pro-punch:'||aid::text) placing '4' from 13) placing '8' from 17)::uuid;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-punch-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_punch_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 if photo is not null and not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=photo and ready and mime_type='image/jpeg') then raise exception 'Photo unavailable' using errcode='22023';end if;
 if act='create' then
  if (select count(*) from public.pro_work_punch_items where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Punch list limit reached' using errcode='54000';end if;
  perform public.pro_work_tasks_mutate(p_actor,jsonb_build_object('action','create','workId',wid,'taskId',tid,'actionId',task_action,'revision',0,'title',p_input->'title','details',p_input->'details','dueDate',p_input->'dueDate','assignee',p_input->'assignee'));
  insert into public.pro_work_punch_items(owner_id,work_id,task_id,photo_file_id,photo_required) values(p_actor,wid,tid,photo,required) returning * into item;
 elsif act='mark' then
  select * into task from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=tid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if task.archived then raise exception 'Restore task first' using errcode='22023';end if;
  if exists(select 1 from public.pro_work_punch_items where owner_id=p_actor and work_id=wid and task_id=tid) then raise exception 'Already in punch list' using errcode='40001';end if;
  if (select count(*) from public.pro_work_punch_items where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Punch list limit reached' using errcode='54000';end if;
  insert into public.pro_work_punch_items(owner_id,work_id,task_id) values(p_actor,wid,tid) returning * into item;
 else
  select * into item from public.pro_work_punch_items where owner_id=p_actor and work_id=wid and task_id=tid for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  before_json:=public.pro_work_punch_json(p_actor,wid,tid);
  if act='update' then
   if (p_input->>'revision')::integer<>item.revision then raise exception 'Punch item changed' using errcode='40001';end if;
   perform public.pro_work_tasks_mutate(p_actor,jsonb_build_object('action','update','workId',wid,'taskId',tid,'actionId',task_action,'revision',p_input->'taskRevision','title',p_input->'title','details',p_input->'details','dueDate',p_input->'dueDate','assignee',p_input->'assignee'));
   update public.pro_work_punch_items set photo_file_id=photo,photo_required=required,revision=revision+1,updated_at=now() where owner_id=p_actor and work_id=wid and task_id=tid returning * into item;
  else
   if act='complete' and item.photo_required and not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=item.photo_file_id and ready and mime_type='image/jpeg') then raise exception 'Photo required before completing' using errcode='22023';end if;
   perform public.pro_work_tasks_mutate(p_actor,jsonb_build_object('action',act,'workId',wid,'taskId',tid,'actionId',task_action,'revision',p_input->'taskRevision'));
  end if;
 end if;
 after_json:=public.pro_work_punch_json(p_actor,wid,tid);result:=jsonb_build_object('item',after_json);
 insert into public.pro_work_punch_history(owner_id,work_id,task_id,action_id,action,before_item,after_item) values(p_actor,wid,tid,aid,act,before_json,after_json);
 insert into public.pro_work_punch_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

create or replace function public.pro_work_punchlist_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;req_status text;enabled boolean;items jsonb;total integer;done integer;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select coalesce(show_punchlist,false) into enabled from public.pro_client_dashboards where owner_id=owner and work_id=wid;
 if req_status not in('confirmed','completed') or not coalesce(enabled,false) then return jsonb_build_object('visible',false);end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.task_id,'title',x.title,'status',x.status,'dueDate',case when x.due_date is null then null else to_char(x.due_date,'YYYY-MM-DD') end,'hasPhoto',x.has_photo) order by x.due_date nulls last,x.created_at,x.task_id),'[]'::jsonb),
  count(*),count(*) filter(where x.status='done') into items,total,done
 from (select p.task_id,p.created_at,t.title,t.status,t.due_date,exists(select 1 from public.pro_work_files f where f.owner_id=p.owner_id and f.work_id=p.work_id and f.id=p.photo_file_id and f.ready and f.mime_type='image/jpeg') has_photo
  from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
  where p.owner_id=owner and p.work_id=wid and not t.archived order by t.due_date nulls last,p.created_at,p.task_id limit 500) x;
 return jsonb_build_object('visible',true,'items',items,'counts',jsonb_build_object('total',coalesce(total,0),'done',coalesce(done,0)));
end $$;

-- Photo access is re-authorized per request: the owner, or the linked customer of a
-- confirmed/completed request whose customer view shows the punch list.
create or replace function public.pro_work_punch_image(p_actor uuid,p_task uuid,p_request uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;file_row public.pro_work_files;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is null then
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
  owner:=p_actor;select work_id into wid from public.pro_work_punch_items where owner_id=p_actor and task_id=p_task limit 1;
  if wid is null then return null;end if;
 else
  select r.owner_id,r.work_id into owner,wid from public.pro_appointment_requests r join public.pro_client_dashboards d on d.owner_id=r.owner_id and d.work_id=r.work_id
   where r.id=p_request and r.client_user_id=p_actor and r.status in('confirmed','completed') and d.show_punchlist;
  if not found then return null;end if;
 end if;
 select f.* into file_row from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived
  join public.pro_work_files f on f.owner_id=p.owner_id and f.work_id=p.work_id and f.id=p.photo_file_id and f.ready and f.mime_type='image/jpeg'
  where p.owner_id=owner and p.work_id=wid and p.task_id=p_task;
 if not found then return null;end if;
 return jsonb_build_object('objectPath',file_row.object_path,'mimeType',file_row.mime_type,'sizeBytes',file_row.size_bytes,'sha256',file_row.sha256);
end $$;

alter table public.pro_work_punch_items enable row level security;
alter table public.pro_work_punch_history enable row level security;
alter table public.pro_work_punch_actions enable row level security;
revoke all on public.pro_work_punch_items,public.pro_work_punch_history,public.pro_work_punch_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_punch_items,public.pro_work_punch_history,public.pro_work_punch_actions to service_role;
revoke all on function public.pro_work_punch_immutable(),public.pro_work_punch_photo_guard(),public.pro_work_punch_json(uuid,text,uuid),public.pro_work_punchlist_read(uuid,text),public.pro_work_punchlist_mutate(uuid,jsonb),public.pro_work_punchlist_client_read(uuid,uuid),public.pro_work_punch_image(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_work_punch_json(uuid,text,uuid),public.pro_work_punchlist_read(uuid,text),public.pro_work_punchlist_mutate(uuid,jsonb),public.pro_work_punchlist_client_read(uuid,uuid),public.pro_work_punch_image(uuid,uuid,uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== time-tracking-local.sql =====
-- LOCAL PRO ONLY. Own time tracking (families 21/22): activities with an hourly
-- rate (CRC cents) and optional internal cost, one running timer per account kept
-- on the server, and manual entries. A stopped or manual entry becomes exactly one
-- existing job-cost time line (pro_work_costs_mutate 'add_time'), so job costs
-- count every minute once; voiding uses the existing 'void_time' reversal.
-- No payroll, no clock-in for third parties, no invoices or notifications.
begin;
create table if not exists public.pro_time_activities(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 80),
 rate_cents bigint not null check(rate_cents between 0 and 10000000000),
 cost_cents bigint check(cost_cents is null or cost_cents between 0 and 10000000000),
 billable boolean not null default true,archived boolean not null default false,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id)
);
create table if not exists public.pro_time_entries(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,work_id text not null,activity_id uuid,
 source text not null check(source in('timer','manual')),status text not null check(status in('running','stopped','discarded')),
 started_at timestamptz,stopped_at timestamptz,minutes integer,recorded_on date,
 billable boolean not null,rate_cents bigint check(rate_cents is null or rate_cents between 0 and 10000000000),
 cost_cents bigint check(cost_cents is null or cost_cents between 0 and 10000000000),
 note text not null default '' check(length(note)<=300),cost_entry_id uuid,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),
 primary key(owner_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,activity_id) references public.pro_time_activities(owner_id,id),
 foreign key(owner_id,cost_entry_id) references public.pro_work_cost_entries(user_id,id),
 check((status='running' and source='timer' and started_at is not null and stopped_at is null and minutes is null and recorded_on is null and cost_entry_id is null)
  or(status='discarded' and source='timer' and started_at is not null and stopped_at is not null and minutes is null and cost_entry_id is null)
  or(status='stopped' and minutes between 1 and 1440 and recorded_on is not null and cost_entry_id is not null and(source='manual' or(started_at is not null and stopped_at is not null))))
);
-- One running timer per account, across every job and tab.
create unique index if not exists pro_time_entries_one_running on public.pro_time_entries(owner_id) where status='running';
create unique index if not exists pro_time_entries_cost_line on public.pro_time_entries(owner_id,cost_entry_id) where cost_entry_id is not null;
create index if not exists pro_time_entries_work_page on public.pro_time_entries(owner_id,work_id,recorded_on desc,created_at desc);
create table if not exists public.pro_time_history(
 owner_id uuid not null,action_id uuid not null,subject text not null check(subject in('activity','entry')),subject_id uuid not null,
 action text not null,before_row jsonb,after_row jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id)
);
create table if not exists public.pro_time_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create or replace function public.pro_time_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Time history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_time_history_immutable on public.pro_time_history;
create trigger pro_time_history_immutable before update on public.pro_time_history for each row execute function public.pro_time_immutable();
drop trigger if exists pro_time_actions_immutable on public.pro_time_actions;
create trigger pro_time_actions_immutable before update on public.pro_time_actions for each row execute function public.pro_time_immutable();

create or replace function public.pro_time_activity_json(p_row public.pro_time_activities) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'name',p_row.name,'rateCents',p_row.rate_cents,'costCents',p_row.cost_cents,'billable',p_row.billable,'archived',p_row.archived,'revision',p_row.revision);
$$;
-- QA 2026-11-11: an edit in Costs (edit_time) reverses the line and records a new
-- one with id = requestId. Follow that chain to the live line: the entry is void only
-- when the chain ends in a plain reversal; otherwise it is "adjusted in Costs" and its
-- minutes/amounts come from the live line, so Hours and Costs never disagree.
create index if not exists pro_work_cost_requests_edit_time on public.pro_work_cost_requests(user_id,lower(input->>'entryId')) where input->>'action'='edit_time';
create or replace function public.pro_time_live_line(p_owner uuid,p_line uuid) returns uuid
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare cur uuid:=p_line;nxt uuid;
begin
 for i in 1..100 loop
  if cur is null then return null;end if;
  if not exists(select 1 from public.pro_work_cost_entries r where r.user_id=p_owner and r.reversal_id=cur) then return cur;end if;
  nxt:=null;select (q.result->>'id')::uuid into nxt from public.pro_work_cost_requests q where q.user_id=p_owner and q.input->>'action'='edit_time' and lower(q.input->>'entryId')=cur::text limit 1;
  cur:=nxt;
 end loop;
 return null;
end $$;
create or replace function public.pro_time_entry_json(p_row public.pro_time_entries) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'workTitle',(select w.service from public.pro_work w where w.user_id=p_row.owner_id and w.id=p_row.work_id),
  'activityId',p_row.activity_id,'activityName',(select a.name from public.pro_time_activities a where a.owner_id=p_row.owner_id and a.id=p_row.activity_id),
  'source',p_row.source,'status',p_row.status,'startedAt',p_row.started_at,'stoppedAt',p_row.stopped_at,'minutes',coalesce(l.minutes,p_row.minutes),
  'recordedOn',case when p_row.recorded_on is null then null else to_char(p_row.recorded_on,'YYYY-MM-DD') end,
  'billable',p_row.billable,'rateCents',p_row.rate_cents,'costCents',p_row.cost_cents,'note',p_row.note,'costEntryId',p_row.cost_entry_id,
  'billableCents',case when p_row.status='stopped' and p_row.billable and p_row.rate_cents is not null then round(coalesce(l.minutes,p_row.minutes)::numeric*p_row.rate_cents/60)::bigint end,
  'voided',p_row.cost_entry_id is not null and l.id is null,
  'adjusted',l.id is not null and l.id<>p_row.cost_entry_id,
  'revision',p_row.revision)
 from (select 1) one left join public.pro_work_cost_entries l on l.user_id=p_row.owner_id and l.id=public.pro_time_live_line(p_row.owner_id,p_row.cost_entry_id);
$$;

create or replace function public.pro_time_read(p_actor uuid,p_work text,p_from text,p_to text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare first_day date;last_day date;running public.pro_time_entries;activities jsonb;entries jsonb;totals jsonb;by_activity jsonb;ledger jsonb;ledger_totals jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_from is null or p_to is null or not p_from~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not p_to~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid time query' using errcode='22023';end if;
 first_day:=p_from::date;last_day:=p_to::date;
 if first_day<date'1900-01-01' or last_day>date'2100-12-31' or last_day-first_day not between 0 and 366 then raise exception 'Invalid time period' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select * into running from public.pro_time_entries where owner_id=p_actor and status='running';
 select coalesce(jsonb_agg(public.pro_time_activity_json(a) order by a.archived,a.name,a.id),'[]'::jsonb) into activities from (select * from public.pro_time_activities where owner_id=p_actor order by archived,name,id limit 100) a;
 select coalesce(jsonb_agg(public.pro_time_entry_json(e) order by e.recorded_on desc,e.created_at desc,e.id),'[]'::jsonb) into entries
  from (select * from public.pro_time_entries where owner_id=p_actor and work_id=p_work and status='stopped' and recorded_on between first_day and last_day order by recorded_on desc,created_at desc,id limit 200) e;
 with live as(select e.owner_id,e.activity_id,e.billable,e.rate_cents,l.minutes,l.hourly_cost_cents line_cost,l.amount_cents line_amount,a.name activity_name
   from public.pro_time_entries e join public.pro_work_cost_entries l on l.user_id=e.owner_id and l.id=public.pro_time_live_line(e.owner_id,e.cost_entry_id)
   left join public.pro_time_activities a on a.owner_id=e.owner_id and a.id=e.activity_id
   where e.owner_id=p_actor and e.work_id=p_work and e.status='stopped' and e.recorded_on between first_day and last_day)
 select jsonb_build_object('entries',count(*),'minutes',coalesce(sum(minutes),0),'billableMinutes',coalesce(sum(minutes) filter(where billable),0),
   'billableCents',coalesce(sum(round(minutes::numeric*rate_cents/60)) filter(where billable and rate_cents is not null),0)::bigint,
   'costCents',coalesce(sum(line_amount) filter(where line_cost is not null),0)::bigint,
   'uncostedMinutes',coalesce(sum(minutes) filter(where line_cost is null),0)),
  coalesce((select jsonb_agg(jsonb_build_object('activityId',g.activity_id,'name',g.activity_name,'minutes',g.minutes,'billableCents',g.billable_cents) order by g.minutes desc,g.activity_name nulls last)
   from (select activity_id,activity_name,sum(minutes) minutes,coalesce(sum(round(minutes::numeric*rate_cents/60)) filter(where billable and rate_cents is not null),0)::bigint billable_cents from live group by activity_id,activity_name) g),'[]'::jsonb)
 into totals,by_activity from live;
 -- Round 1 (2026-11-12): ONE time ledger. Hours recorded directly in «Costos y pagos» (live time lines of
 -- pro_work_cost_entries not produced by this module) are listed here read-only (source 'ledger') and
 -- counted in the totals, so «Horas» and «Costos y pagos» always show the same hours.
 with mine as(select public.pro_time_live_line(e.owner_id,e.cost_entry_id) line from public.pro_time_entries e where e.owner_id=p_actor and e.work_id=p_work and e.cost_entry_id is not null),
 lines as(select l.* from public.pro_work_cost_entries l where l.user_id=p_actor and l.work_id=p_work and l.kind='time' and l.recorded_on between first_day and last_day
   and not exists(select 1 from public.pro_work_cost_entries r where r.user_id=l.user_id and r.reversal_id=l.id)
   and not exists(select 1 from mine where mine.line=l.id)
   and not exists(select 1 from public.pro_time_entries e where e.owner_id=p_actor and e.cost_entry_id=l.id))
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'workId',l.work_id,'workTitle',(select w.service from public.pro_work w where w.user_id=p_actor and w.id=l.work_id),'activityId',null,'activityName',null,
   'source','ledger','status','stopped','startedAt',null,'stoppedAt',null,'minutes',l.minutes,'recordedOn',to_char(l.recorded_on,'YYYY-MM-DD'),'billable',false,'rateCents',null,'costCents',l.hourly_cost_cents,
   'note',l.note,'costEntryId',l.id,'billableCents',null,'voided',false,'adjusted',false,'revision',1) order by l.recorded_on desc,l.created_at desc,l.id),'[]'::jsonb),
  jsonb_build_object('entries',count(*),'minutes',coalesce(sum(l.minutes),0),'costCents',coalesce(sum(l.amount_cents) filter(where l.hourly_cost_cents is not null),0),'uncostedMinutes',coalesce(sum(l.minutes) filter(where l.hourly_cost_cents is null),0))
 into ledger,ledger_totals from (select * from lines order by recorded_on desc,created_at desc,id limit 200) l;
 select coalesce(jsonb_agg(x order by x->>'recordedOn' desc),'[]'::jsonb) into entries from (select jsonb_array_elements(entries) x union all select jsonb_array_elements(ledger)) y(x);
 if jsonb_array_length(entries)>200 then select jsonb_agg(x) into entries from (select x from jsonb_array_elements(entries) with ordinality t(x,n) where n<=200 order by n) z;end if;
 totals:=totals||jsonb_build_object('entries',(totals->>'entries')::bigint+(ledger_totals->>'entries')::bigint,'minutes',(totals->>'minutes')::bigint+(ledger_totals->>'minutes')::bigint,
  'costCents',(totals->>'costCents')::bigint+(ledger_totals->>'costCents')::bigint,'uncostedMinutes',(totals->>'uncostedMinutes')::bigint+(ledger_totals->>'uncostedMinutes')::bigint);
 if (ledger_totals->>'minutes')::bigint>0 then by_activity:=by_activity||jsonb_build_array(jsonb_build_object('activityId',null,'name',null,'minutes',(ledger_totals->>'minutes')::bigint,'billableCents',0));end if;
 return jsonb_build_object('workId',p_work,'serverNow',clock_timestamp(),'period',jsonb_build_object('from',p_from,'to',p_to),
  'running',case when running.id is null then null else public.pro_time_entry_json(running) end,
  'activities',activities,'entries',entries,'totals',totals||jsonb_build_object('byActivity',by_activity));
end $$;

-- Records one job-cost time line through the existing writer (same lock, current revision).
create or replace function public.pro_time_cost_line(p_actor uuid,p_work text,p_request uuid,p_day date,p_minutes integer,p_cost bigint,p_note text) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare cid text;rev bigint;answer jsonb;
begin
 select "clientId" into cid from public.pro_work where user_id=p_actor and id=p_work;
 if cid is null then raise exception 'Job without customer' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('work-costs:'||p_actor::text,0));
 insert into public.pro_work_cost_state(user_id) values(p_actor) on conflict do nothing;
 select revision into rev from public.pro_work_cost_state where user_id=p_actor;
 answer:=public.pro_work_costs_mutate(p_actor,jsonb_build_object('action','add_time','clientId',cid,'workId',p_work,'requestId',p_request,'revision',rev,
  'date',to_char(p_day,'YYYY-MM-DD'),'minutes',p_minutes,'hourlyCostCents',p_cost,'note',left(p_note,300)));
 return (answer->>'id')::uuid;
end $$;

create or replace function public.pro_time_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;eid uuid;keys text[];expected text[];receipt public.pro_time_actions;a public.pro_time_activities;e public.pro_time_entries;w public.pro_work;
 before_json jsonb;after_json jsonb;result jsonb;subject text;sid uuid;v_name text;v_rate bigint;v_cost bigint;v_note text;v_minutes integer;v_day date;elapsed numeric;cost_line uuid;rev bigint;cid text;already boolean:=false;today date;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid time operation' using errcode='22023';end if;
 act:=p_input->>'action';
 expected:=case act
  when 'activity_save' then array['action','actionId','activityId','billable','costCents','name','rateCents','revision']
  when 'activity_archive' then array['action','actionId','activityId','revision'] when 'activity_restore' then array['action','actionId','activityId','revision']
  when 'start' then array['action','actionId','activityId','billable','entryId','note','workId']
  when 'stop' then array['action','actionId','entryId','minutes','note']
  when 'discard' then array['action','actionId','entryId']
  when 'manual' then array['action','actionId','activityId','billable','date','entryId','minutes','note','workId']
  when 'void' then array['action','actionId','entryId','reason','revision'] end;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if expected is null or keys is distinct from expected then raise exception 'Invalid time fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;today:=(now() at time zone 'America/Costa_Rica')::date;
 if act like 'activity_%' then
  if jsonb_typeof(p_input->'activityId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid activity identity' using errcode='22023';end if;
  if act='activity_save' then
   if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'rateCents') is distinct from 'number' or jsonb_typeof(p_input->'costCents') not in('number','null') or jsonb_typeof(p_input->'billable') is distinct from 'boolean'
    or not coalesce((p_input->>'rateCents')~'^[0-9]{1,11}$',false) or (p_input->>'costCents' is not null and not coalesce((p_input->>'costCents')~'^[0-9]{1,11}$',false)) then raise exception 'Invalid activity fields' using errcode='22023';end if;
   v_name:=btrim(p_input->>'name');v_rate:=(p_input->>'rateCents')::bigint;v_cost:=(p_input->>'costCents')::bigint;
   if length(v_name) not between 1 and 80 or v_rate>10000000000 or v_cost>10000000000 then raise exception 'Invalid activity values' using errcode='22023';end if;
  end if;
 else
  if jsonb_typeof(p_input->'entryId') is distinct from 'string' then raise exception 'Invalid entry identity' using errcode='22023';end if;
  eid:=(p_input->>'entryId')::uuid;
  if act in('start','manual') then
   if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 or jsonb_typeof(p_input->'activityId') not in('string','null') or jsonb_typeof(p_input->'billable') is distinct from 'boolean' then raise exception 'Invalid entry fields' using errcode='22023';end if;
  end if;
  if act in('start','manual','stop') then
   if jsonb_typeof(p_input->'note') is distinct from 'string' or length(btrim(p_input->>'note'))>300 then raise exception 'Invalid note' using errcode='22023';end if;v_note:=btrim(p_input->>'note');
  end if;
  if act in('manual','stop') then
   if act='manual' and jsonb_typeof(p_input->'minutes') is distinct from 'number' or jsonb_typeof(p_input->'minutes') not in('number','null') then raise exception 'Invalid minutes' using errcode='22023';end if;
   if p_input->>'minutes' is not null then
    if not coalesce((p_input->>'minutes')~'^[0-9]{1,4}$',false) or (p_input->>'minutes')::integer not between 1 and 1440 then raise exception 'Invalid minutes' using errcode='22023';end if;
    v_minutes:=(p_input->>'minutes')::integer;
   end if;
  end if;
  if act='manual' then
   if jsonb_typeof(p_input->'date') is distinct from 'string' or not coalesce((p_input->>'date')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid date' using errcode='22023';end if;
   v_day:=(p_input->>'date')::date;if to_char(v_day,'YYYY-MM-DD')<>p_input->>'date' or v_day<date'1900-01-01' or v_day>today then raise exception 'Invalid date' using errcode='22023';end if;
  end if;
  if act='void' then
   if jsonb_typeof(p_input->'reason') is distinct from 'string' or length(btrim(p_input->>'reason')) not between 1 and 300 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid void' using errcode='22023';end if;
  end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-time-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_time_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 -- Every timer/entry change of the account is serialized: one running session, no lost stop.
 perform pg_advisory_xact_lock(hashtextextended('pro-time:'||p_actor::text,0));
 if act like 'activity_%' then
  subject:='activity';sid:=(p_input->>'activityId')::uuid;
  select * into a from public.pro_time_activities where owner_id=p_actor and id=sid for update;
  if found then
   before_json:=public.pro_time_activity_json(a);
   if (p_input->>'revision')::integer<>a.revision then raise exception 'Activity changed' using errcode='40001';end if;
   if act='activity_save' then
    if a.archived then raise exception 'Restore the activity first' using errcode='22023';end if;
    update public.pro_time_activities set name=v_name,rate_cents=v_rate,cost_cents=v_cost,billable=(p_input->>'billable')::boolean,revision=revision+1,updated_at=now() where owner_id=p_actor and id=sid returning * into a;
   else
    if a.archived=(act='activity_archive') then raise exception 'Invalid archive transition' using errcode='22023';end if;
    update public.pro_time_activities set archived=(act='activity_archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and id=sid returning * into a;
   end if;
  else
   if act<>'activity_save' or (p_input->>'revision')::integer<>0 then raise exception 'Activity changed' using errcode='40001';end if;
   if (select count(*) from public.pro_time_activities where owner_id=p_actor)>=100 then raise exception 'Activity limit reached' using errcode='54000';end if;
   insert into public.pro_time_activities(owner_id,id,name,rate_cents,cost_cents,billable) values(p_actor,sid,v_name,v_rate,v_cost,(p_input->>'billable')::boolean) returning * into a;
  end if;
  after_json:=public.pro_time_activity_json(a);result:=jsonb_build_object('activity',after_json);
 else
  subject:='entry';sid:=eid;
  if act in('start','manual') then
   select * into w from public.pro_work where user_id=p_actor and id=p_input->>'workId';
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   if w.cancelled or exists(select 1 from public.pro_clients c where c.user_id=p_actor and c.id=w."clientId" and c.archived) then raise exception 'Inactive job' using errcode='22023';end if;
   if exists(select 1 from public.pro_time_entries where owner_id=p_actor and id=eid) then raise exception 'Entry identity already exists' using errcode='22023';end if;
   if p_input->>'activityId' is not null then
    select * into a from public.pro_time_activities where owner_id=p_actor and id=(p_input->>'activityId')::uuid;
    if not found or a.archived then raise exception 'Activity unavailable' using errcode='40001';end if;
   end if;
   if act='start' then
    if exists(select 1 from public.pro_time_entries where owner_id=p_actor and status='running') then raise exception 'Another timer is running' using errcode='40001';end if;
    insert into public.pro_time_entries(owner_id,id,work_id,activity_id,source,status,started_at,billable,rate_cents,cost_cents,note)
     values(p_actor,eid,w.id,a.id,'timer','running',clock_timestamp(),(p_input->>'billable')::boolean,a.rate_cents,a.cost_cents,v_note) returning * into e;
   else
    cost_line:=public.pro_time_cost_line(p_actor,w.id,overlay(overlay(md5('pro-time:'||eid::text) placing '4' from 13) placing '8' from 17)::uuid,v_day,v_minutes,a.cost_cents,concat_ws(' · ',a.name,nullif(v_note,'')));
    insert into public.pro_time_entries(owner_id,id,work_id,activity_id,source,status,minutes,recorded_on,billable,rate_cents,cost_cents,note,cost_entry_id)
     values(p_actor,eid,w.id,a.id,'manual','stopped',v_minutes,v_day,(p_input->>'billable')::boolean,a.rate_cents,a.cost_cents,v_note,cost_line) returning * into e;
   end if;
  else
   select * into e from public.pro_time_entries where owner_id=p_actor and id=eid for update;
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   before_json:=public.pro_time_entry_json(e);
   if act='stop' then
    if e.status='stopped' then already:=true;
    elsif e.status='discarded' then raise exception 'Timer was discarded' using errcode='40001';
    else
     elapsed:=extract(epoch from clock_timestamp()-e.started_at)/60;
     if v_minutes is null then
      if elapsed>1440 then raise exception 'Timer longer than a day; enter the minutes' using errcode='22023';end if;
      v_minutes:=greatest(1,round(elapsed))::integer;
     elsif v_minutes>greatest(1,ceil(elapsed)) then raise exception 'Minutes exceed the elapsed time' using errcode='22023';end if;
     v_day:=today;
     cost_line:=public.pro_time_cost_line(p_actor,e.work_id,overlay(overlay(md5('pro-time:'||eid::text) placing '4' from 13) placing '8' from 17)::uuid,v_day,v_minutes,e.cost_cents,
      concat_ws(' · ',(select x.name from public.pro_time_activities x where x.owner_id=p_actor and x.id=e.activity_id),nullif(coalesce(nullif(v_note,''),e.note),'')));
     update public.pro_time_entries set status='stopped',stopped_at=clock_timestamp(),minutes=v_minutes,recorded_on=v_day,note=coalesce(nullif(v_note,''),note),cost_entry_id=cost_line,revision=revision+1 where owner_id=p_actor and id=eid returning * into e;
    end if;
   elsif act='discard' then
    if e.status<>'running' then raise exception 'Timer is not running' using errcode='40001';end if;
    update public.pro_time_entries set status='discarded',stopped_at=clock_timestamp(),revision=revision+1 where owner_id=p_actor and id=eid returning * into e;
   else
    if e.status<>'stopped' or (p_input->>'revision')::integer<>e.revision then raise exception 'Entry changed' using errcode='40001';end if;
    cost_line:=public.pro_time_live_line(p_actor,e.cost_entry_id);-- the current line, also after an edit in Costs
    if cost_line is null then raise exception 'Entry already void' using errcode='40001';end if;
    select "clientId" into cid from public.pro_work where user_id=p_actor and id=e.work_id;
    perform pg_advisory_xact_lock(hashtextextended('work-costs:'||p_actor::text,0));
    insert into public.pro_work_cost_state(user_id) values(p_actor) on conflict do nothing;
    select revision into rev from public.pro_work_cost_state where user_id=p_actor;
    perform public.pro_work_costs_mutate(p_actor,jsonb_build_object('action','void_time','clientId',cid,'workId',e.work_id,'requestId',overlay(overlay(md5('pro-time-void:'||eid::text) placing '4' from 13) placing '8' from 17)::uuid,'revision',rev,'entryId',cost_line,'reason',btrim(p_input->>'reason')));
    update public.pro_time_entries set revision=revision+1 where owner_id=p_actor and id=eid returning * into e;
   end if;
  end if;
  after_json:=public.pro_time_entry_json(e);result:=jsonb_build_object('entry',after_json,'alreadyStopped',already);
 end if;
 insert into public.pro_time_history(owner_id,action_id,subject,subject_id,action,before_row,after_row) values(p_actor,aid,subject,sid,act,before_json,after_json);
 insert into public.pro_time_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

alter table public.pro_time_activities enable row level security;
alter table public.pro_time_entries enable row level security;
alter table public.pro_time_history enable row level security;
alter table public.pro_time_actions enable row level security;
revoke all on public.pro_time_activities,public.pro_time_entries,public.pro_time_history,public.pro_time_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_time_activities,public.pro_time_entries,public.pro_time_history,public.pro_time_actions to service_role;
revoke all on function public.pro_time_immutable(),public.pro_time_live_line(uuid,uuid),public.pro_time_activity_json(public.pro_time_activities),public.pro_time_entry_json(public.pro_time_entries),public.pro_time_read(uuid,text,text,text),public.pro_time_cost_line(uuid,text,uuid,date,integer,bigint,text),public.pro_time_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_time_live_line(uuid,uuid),public.pro_time_activity_json(public.pro_time_activities),public.pro_time_entry_json(public.pro_time_entries),public.pro_time_read(uuid,text,text,text),public.pro_time_cost_line(uuid,text,uuid,date,integer,bigint,text),public.pro_time_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;
